@Service @Transactional
public class FinanceBusinessService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext db;private final AccessPolicy access;private final AuditWriter audit;private final ObjectMapper mapper;private final FinanceAccountingService accounting;
 private static final Set<String> TAX_SOURCES=Set.of("OUTPUT_NET","OUTPUT_TAX","INPUT_CLAIMED","INPUT_TRANSFER_OUT","INCOME_NET","INCOME_TAX","POSTED_DEBIT","POSTED_CREDIT");
 public FinanceBusinessService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext db,AccessPolicy access,AuditWriter audit,ObjectMapper mapper,FinanceAccountingService accounting){this.jdbc=jdbc;this.db=db;this.access=access;this.audit=audit;this.mapper=mapper;this.accounting=accounting;}
 public Map<String,Object> context(){var p=prepare("finance.read","finance.review","finance.pay","finance.configure","finance.payroll","finance.tax","finance.accounting.read");var out=new LinkedHashMap<String,Object>();
  out.put("hotels",rows("select id,name from org_unit where tenant_id=:tenantId and status='ACTIVE' and unit_type in ('HOTEL','GROUP') and (:tenantScope or id in (:scopeIds)) order by name",base(p)));
  out.put("externalConnections",Map.of("pms","FILE_IMPORT_ONLY","ota","FILE_IMPORT_ONLY","invoice","NOT_CONFIGURED","taxFiling","NOT_CONFIGURED"));
  out.put("limitations",List.of("银行到账不直接当收入；预收/押金/储值与营业收入分开","工资和税务分别授权；管理员名称不代替权限","合并底稿仅使用已过账并已映射的双方内部事实；复杂权益、多币种未纳入","开票及申报未接外部接口，只能登记并上传真实结果"));return out;}
 public Map<String,Object> cancelDraft(String domain,UUID id,Confirm in){var p=prepare("finance.submit","finance.review");if(domain.equals("PAYROLL"))access.requirePermission("finance.payroll");String table=switch(domain){case "REVENUE"->"fb_revenue_batch";case "PAYROLL"->"fb_payroll_batch";case "INTERCOMPANY"->"fb_intercompany";default->throw bad("资料域未知");};if(replay(p,in.requestId(),id,"DRAFT_CANCEL_"+domain,in))return Map.of("id",id,"status","CANCELLED");var row=domain.equals("INTERCOMPANY")?bilateral(id,p,true):load(table,id,p,true);version(row,in.expectedVersion());UUID creator=uid(row,domain.equals("INTERCOMPANY")?"creator_id":"created_by");boolean own=creator.equals(p.actorId())&&has(p,"finance.submit"),reviewer=has(p,"finance.review")&&(p.actorId().equals(uid(row,"reviewer_id"))||domain.equals("INTERCOMPANY")&&p.actorId().equals(uid(row,"counterparty_reviewer_id")));if(!own&&!reviewer)throw forbidden();if(domain.equals("INTERCOMPANY")&&p.actorId().equals(uid(row,"counterparty_reviewer_id")))access.requireOrgScope(uid(row,"counterparty_hotel_id"));if(!str(row,"status").equals("REVIEW"))throw conflict("仅尚未完成独立确认的资料可撤销；已确认事实须保留来源更正");jdbc.update("update "+table+" set status='CANCELLED',version=version+1 where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));record(p,in.requestId(),id,"DRAFT_CANCEL_"+domain,in);return Map.of("id",id,"status","CANCELLED");}
 public Map<String,Object> revenueImports(){var p=prepare("finance.read","finance.review");return list("select d.* from fb_revenue_batch d where d.tenant_id=:tenantId and "+scope("d")+" order by d.created_at desc,d.id",base(p));}
 public Map<String,Object> revenueMovements(){var p=prepare("finance.read","finance.review","finance.pay");return list("select m.*,e.hotel_id,e.external_id,e.customer,fb_cash_effective_amount(m.tenant_id,'REVENUE',m.id,m.amount,:asOf) effective_amount from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id where m.tenant_id=:tenantId and "+scope("e")+" order by m.occurred_on desc,m.id",base(p));}
 public Map<String,Object> previewRevenue(RevenueImport in){var p=prepare("finance.read","finance.review");company(p,in.hotelId());validateRevenue(in);return Map.of("valid",true,"rowCount",in.rows().size(),"controlTotal",money(in.controlTotal()).toPlainString(),"hash",hash(in),"commitRequiresOriginal",true,"externalConnected",false);}
 public Map<String,Object> importRevenue(RevenueImport in){var p=prepare("finance.read","finance.review");access.requirePermission("finance.submit");UUID company=company(p,in.hotelId());validateRevenue(in);account(p,in.reviewerId());independent(p,in.reviewerId());
  if(replay(p,in.requestId(),in.requestId(),"REVENUE_IMPORT",in))return revenueDetail(in.requestId());
  lock(p,"revenue:"+in.hotelId()+in.source()+in.channel()+in.businessDate());var b=base(p).addValue("hotel",in.hotelId()).addValue("source",in.source()).addValue("channel",in.channel()).addValue("day",in.businessDate());
  Integer revision=jdbc.queryForObject("select coalesce(max(revision),0) from fb_revenue_batch where tenant_id=:tenantId and hotel_id=:hotel and source=:source and channel=:channel and business_date=:day",b,Integer.class);
  if(in.revision()!=revision+1)throw conflict("导入修订版本应连续，当前应为 "+(revision+1));
  if(revision>0&&jdbc.queryForObject("select count(*) from fb_revenue_batch where tenant_id=:tenantId and hotel_id=:hotel and source=:source and channel=:channel and business_date=:day and status='REVIEW'",b,Integer.class)>0)throw conflict("前一修订尚待复核，不可并行覆盖");
  b.addValue("id",in.requestId()).addValue("company",company).addValue("night",in.nightAuditDate()).addValue("revision",in.revision()).addValue("count",in.expectedCount()).addValue("total",money(in.controlTotal())).addValue("reference",in.sourceReference()).addValue("hash",hash(in)).addValue("reviewer",in.reviewerId());
  jdbc.update("insert into fb_revenue_batch(id,tenant_id,hotel_id,company_id,source,channel,business_date,night_audit_date,revision,expected_count,control_total,source_reference,source_hash,created_by,reviewer_id) values(:id,:tenantId,:hotel,:company,:source,:channel,:day,:night,:revision,:count,:total,:reference,:hash,:actorId,:reviewer)",b);
  for(var row:in.rows()){
   var old=jdbc.queryForList("select e.* from fb_revenue_entry e join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id where e.tenant_id=:tenantId and e.hotel_id=:hotel and b.source=:source and b.channel=:channel and b.business_date=:day and e.external_id=:external and e.active for update of e",b.addValue("external",row.externalId()));
   UUID previous=old.isEmpty()?null:uid(old.getFirst(),"id");if(!old.isEmpty()&&!str(old.getFirst(),"kind").equals(row.kind()))throw conflict("重结不能改变原经济性质，应另建调整来源");
   if(!old.isEmpty()&&!company.equals(uid(old.getFirst(),"company_id")))throw conflict("法人主体已调整，不得把旧主体应收、实收或储值静默迁入新主体；请先核对独立迁移与内部往来");if(!old.isEmpty()&&!str(old.getFirst(),"customer").equals(row.customer()))throw conflict("重结不能静默变更原客户或储值归属，须保留独立更正依据");
   var line=base(p).addValue("id",UUID.randomUUID()).addValue("batch",in.requestId()).addValue("hotel",in.hotelId()).addValue("company",company).addValue("external",row.externalId()).addValue("kind",row.kind()).addValue("customer",row.customer()).addValue("channel",in.channel()).addValue("due",row.dueDate()).addValue("amount",money(row.amount())).addValue("net",money(row.netAmount())).addValue("tax",money(row.taxAmount())).addValue("commission",money(row.commission())).addValue("fee",money(row.fee())).addValue("previous",previous);
   jdbc.update("insert into fb_revenue_entry(id,tenant_id,batch_id,hotel_id,company_id,external_id,kind,customer,channel,due_date,amount,net_amount,tax_amount,commission,fee,previous_id) values(:id,:tenantId,:batch,:hotel,:company,:external,:kind,:customer,:channel,:due,:amount,:net,:tax,:commission,:fee,:previous)",line);
  }
  // A replacement batch is a complete snapshot, not an undocumented partial update.
  int previousCount=jdbc.queryForObject("select count(*) from fb_revenue_entry e join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id where e.tenant_id=:tenantId and e.hotel_id=:hotel and b.source=:source and b.channel=:channel and b.business_date=:day and e.active and e.external_id not in (:externals)",b.addValue("externals",in.rows().stream().map(RevenueRow::externalId).toList()),Integer.class);
  if(previousCount>0)throw conflict("重结快照漏掉原来源行；请保留该行并以实际调整处理，不能静默删除已确认收入");
  record(p,in.requestId(),in.requestId(),"REVENUE_IMPORT",in);notifyReview(p,"FINANCE_REVENUE",in.requestId(),in.reviewerId(),0);return revenueDetail(in.requestId());
 }
 private void validateRevenue(RevenueImport in){
  if(!Set.of("PMS","OTA","CUSTOMER","CHANNEL").contains(in.source())||!in.nightAuditClosed())throw bad("来源无效或夜审尚未关闭，不可确认完整日结");
  if(in.rows().isEmpty()||in.rows().size()>5000||in.expectedCount()!=in.rows().size())throw bad("来源控制行数与实际不符");Set<String> ids=new HashSet<>();BigDecimal sum=BigDecimal.ZERO;
  for(var r:in.rows()){if(!ids.add(r.externalId())||!Set.of("INCOME","AR","DEPOSIT","PREPAYMENT","STORED_VALUE").contains(r.kind()))throw bad("来源行重复或经济性质未知");positive(r.amount());nonnegative(r.netAmount());nonnegative(r.taxAmount());nonnegative(r.commission());nonnegative(r.fee());if(money(r.amount()).compareTo(money(r.netAmount()).add(money(r.taxAmount())))!=0||r.commission().add(r.fee()).compareTo(r.amount())>0)throw bad("含税/不含税/税额或渠道扣费不平");if(Set.of("DEPOSIT","PREPAYMENT","STORED_VALUE").contains(r.kind())&&(r.commission().signum()!=0||r.fee().signum()!=0||r.taxAmount().signum()!=0))throw bad("押金/预收/储值不得直接混入营业税额或佣金；需分行记录真实收入结算费用");sum=sum.add(r.amount());}
  if(sum.compareTo(money(in.controlTotal()))!=0)throw bad("来源控制金额不平，整批未导入");
 }
 public Map<String,Object> revenueDetail(UUID id){var p=prepare("finance.read","finance.review");var d=load("fb_revenue_batch",id,p,false);var out=external(d);out.put("entries",rows("select * from fb_revenue_entry where tenant_id=:tenantId and batch_id=:id order by external_id",base(p).addValue("id",id)));out.put("attachments",attachments(p,"REVENUE",id));return out;}
 public Map<String,Object> confirmRevenue(UUID id,Confirm in){var p=prepare("finance.review");if(replay(p,in.requestId(),id,"REVENUE_CONFIRM",in))return revenueDetail(id);var d=load("fb_revenue_batch",id,p,true);version(d,in.expectedVersion());reviewer(p,d,"created_by","reviewer_id");requireOriginal(p,"REVENUE",id);if(!str(d,"status").equals("REVIEW"))throw conflict("导入已处理");
  jdbc.update("update fb_revenue_batch set status='CONFIRMED',confirmed_by=:actorId,version=version+1 where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));
  var entries=jdbc.queryForList("select * from fb_revenue_entry where tenant_id=:tenantId and batch_id=:id order by external_id for update",base(p).addValue("id",id));
  for(var row:entries){Map<String,Object> old=uid(row,"previous_id")==null?null:raw("fb_revenue_entry",uid(row,"previous_id"),p,true);if(old!=null){
    BigDecimal settled=movement(p,old,"RECEIPT").subtract(movement(p,old,"REFUND")).add(redeemedInto(p,old)).add(adjustedInto(p,old));BigDecimal redeemed=movement(p,old,"REDEEM");if(settled.compareTo(dec(row,"amount").subtract(dec(row,"commission")).subtract(dec(row,"fee")))>0||redeemed.compareTo(dec(row,"amount"))>0)throw conflict("重结金额低于已收/已核销金额，请先受控退款或调整");
    jdbc.update("update fb_revenue_entry set active=false where tenant_id=:tenantId and id=:id",base(p).addValue("id",uid(old,"id")));
   }
   if(reservedInvoiceAmount(p,row).compareTo(dec(row,"amount"))>0)throw conflict("重结金额低于跨修订已开票/排队金额，请先完成真实红冲及额度核对");
   jdbc.update("update fb_revenue_entry set active=true where tenant_id=:tenantId and id=:id",base(p).addValue("id",uid(row,"id")));
   for(String part:List.of("net_amount","tax_amount","commission","fee")){BigDecimal delta=dec(row,part).subtract(old==null?BigDecimal.ZERO:dec(old,part));if(delta.signum()!=0)event(p,row,"fb_revenue_entry","FB_REVENUE_"+str(row,"kind"),part.toUpperCase(Locale.ROOT)+(delta.signum()<0?"_REVERSAL":""),delta.abs(),date(d,"business_date"),uid(row,"id"),Map.of("batchId",id.toString(),"externalId",str(row,"external_id")));}
  }
  var b=base(p).addValue("id",id);jdbc.update("update fb_revenue_batch set status='SUPERSEDED' where tenant_id=:tenantId and id in(select distinct e.batch_id from fb_revenue_entry e join fb_revenue_entry n on n.tenant_id=e.tenant_id and n.previous_id=e.id where n.tenant_id=:tenantId and n.batch_id=:id)",b);
  record(p,in.requestId(),id,"REVENUE_CONFIRM",in);return revenueDetail(id);
 }
 public Map<String,Object> revenueAccounts(){var p=prepare("finance.read","finance.review","finance.pay");var items=jdbc.queryForList("select e.*,b.business_date,b.source,b.revision from fb_revenue_entry e join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id where e.tenant_id=:tenantId and e.active and "+scope("e")+" order by e.due_date,e.id",base(p));var result=new ArrayList<Map<String,Object>>();for(var row:items){var out=external(row);BigDecimal receipt=movement(p,row,"RECEIPT"),refund=movement(p,row,"REFUND"),redeemed=movement(p,row,"REDEEM"),netExpected=dec(row,"amount").subtract(dec(row,"commission")).subtract(dec(row,"fee")).subtract(adjustedInto(p,row));boolean liability=Set.of("DEPOSIT","PREPAYMENT","STORED_VALUE").contains(str(row,"kind"));out.put("receivedAmount",receipt.toPlainString());out.put("refundAmount",refund.toPlainString());out.put("redeemedAmount",redeemed.toPlainString());out.put("expectedNetReceipt",netExpected.toPlainString());out.put("adjustedAmount",adjustedInto(p,row).toPlainString());out.put("outstandingAmount",(liability?receipt.subtract(refund).subtract(redeemed):netExpected.subtract(receipt).add(refund).subtract(redeemedInto(p,row))).toPlainString());out.put("redeemedAgainstIncomeAmount",redeemedInto(p,row).toPlainString());out.put("balanceBasis",liability?"已实收且尚未退款/消费核销的负债余额":"已确认渠道净应收减真实收款加实际退款");out.put("ageDays",Math.max(0,java.time.temporal.ChronoUnit.DAYS.between(date(row,"due_date"),LocalDate.now())));result.add(out);}return Map.of("items",result,"total",result.size(),"basis","已关闭并独立确认来源；余额包含同外部ID历次重结的现金及核销，不将到账算收入");}
 public Map<String,Object> moveRevenue(UUID entryId,RevenueMovement in){var p=prepare("finance.pay");if(replay(p,in.requestId(),entryId,"REVENUE_MOVEMENT",in))return revenueAccounts();var row=load("fb_revenue_entry",entryId,p,true);if(!Boolean.TRUE.equals(row.get("active")))throw conflict("请使用最新重结版本");positive(in.amount());var cfg=configuration(p,uid(row,"hotel_id"));if(!p.actorId().equals(uid(cfg,"cashier_account_id")))throw forbidden();
  if(!Set.of("RECEIPT","REFUND","REDEEM").contains(in.kind()))throw bad("不支持的资金/核销动作");BigDecimal receipt=movement(p,row,"RECEIPT"),refund=movement(p,row,"REFUND"),redeemed=movement(p,row,"REDEEM"),available=dec(row,"amount").subtract(dec(row,"commission")).subtract(dec(row,"fee")).subtract(adjustedInto(p,row));
  if(in.kind().equals("RECEIPT")&&receipt.subtract(refund).add(redeemedInto(p,row)).add(in.amount()).compareTo(available)>0)throw conflict("累计到账超过结算净额，请以真实差异调整处理");
  if(in.kind().equals("REFUND")&&refund.add(in.amount()).add(redeemed).compareTo(receipt)>0)throw conflict("退款超过未核销实收余额");
  if(in.kind().equals("REDEEM")&&(!Set.of("DEPOSIT","PREPAYMENT","STORED_VALUE").contains(str(row,"kind"))||redeemed.add(refund).add(in.amount()).compareTo(receipt)>0))throw conflict("只能核销预收/押金/储值的实收余额");
  if(in.kind().equals("REDEEM")){if(in.relatedEntryId()==null)throw bad("消费核销必须关联同客户同主体的真实已确认收入/应收，不能再次虚增收入");var income=load("fb_revenue_entry",in.relatedEntryId(),p,true);if(!Boolean.TRUE.equals(income.get("active"))||!Set.of("INCOME","AR").contains(str(income,"kind"))||!uid(income,"hotel_id").equals(uid(row,"hotel_id"))||!uid(income,"company_id").equals(uid(row,"company_id"))||!str(income,"customer").equals(str(row,"customer")))throw bad("消费核销的收入/应收必须同客户、同主体、同门店且为当前有效版本");BigDecimal due=dec(income,"amount").subtract(dec(income,"commission")).subtract(dec(income,"fee")).subtract(movement(p,income,"RECEIPT")).add(movement(p,income,"REFUND")).subtract(redeemedInto(p,income)).subtract(adjustedInto(p,income));if(in.amount().compareTo(due)>0)throw conflict("消费核销超过对应收入/应收的净未清余额");}else if(in.relatedEntryId()!=null)throw bad("只有消费核销可以指定对应收入行");
  jdbc.update("insert into fb_revenue_movement(id,tenant_id,entry_id,related_entry_id,kind,amount,occurred_on,bank_reference,note,created_by) values(:id,:tenantId,:entry,:related,:kind,:amount,:day,:reference,:note,:actorId)",base(p).addValue("id",in.requestId()).addValue("entry",entryId).addValue("kind",in.kind()).addValue("related",in.relatedEntryId()).addValue("amount",money(in.amount())).addValue("day",in.occurredOn()).addValue("reference",in.bankReference()).addValue("note",in.note()));
  event(p,row,"fb_revenue_entry","FB_REVENUE_"+str(row,"kind"),in.kind(),in.amount(),in.occurredOn(),in.requestId(),in.relatedEntryId()==null?Map.of("entryId",entryId.toString()):Map.of("entryId",entryId.toString(),"relatedEntryId",in.relatedEntryId().toString()));record(p,in.requestId(),entryId,"REVENUE_MOVEMENT",in);return revenueAccounts();
 }
 private BigDecimal redeemedInto(TenantPrincipal p,Map<String,Object> row){return jdbc.queryForObject("select coalesce(sum(fb_cash_effective_amount(m.tenant_id,'REVENUE',m.id,m.amount,:asOf)),0) from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.related_entry_id join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id join fb_revenue_batch current_batch on current_batch.tenant_id=b.tenant_id and current_batch.id=:batch where m.tenant_id=:tenantId and m.kind='REDEEM' and e.hotel_id=:hotel and e.external_id=:external and b.source=current_batch.source and b.channel=current_batch.channel and b.business_date=current_batch.business_date",base(p).addValue("batch",row.get("batch_id")).addValue("hotel",row.get("hotel_id")).addValue("external",row.get("external_id")),BigDecimal.class);}
 private BigDecimal movement(TenantPrincipal p,Map<String,Object> row,String kind){return jdbc.queryForObject("select coalesce(sum(fb_cash_effective_amount(m.tenant_id,'REVENUE',m.id,m.amount,:asOf)),0) from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id join fb_revenue_batch current_batch on current_batch.tenant_id=b.tenant_id and current_batch.id=:batch where e.tenant_id=:tenantId and e.hotel_id=:hotel and e.external_id=:external and b.source=current_batch.source and b.channel=current_batch.channel and b.business_date=current_batch.business_date and m.kind=:kind",base(p).addValue("hotel",uid(row,"hotel_id")).addValue("external",str(row,"external_id")).addValue("batch",uid(row,"batch_id")).addValue("kind",kind),BigDecimal.class);}

 public Map<String,Object> payrollBatches(){var p=prepare("finance.payroll");return list("select d.* from fb_payroll_batch d where tenant_id=:tenantId and "+scope("d")+" order by month desc,id",base(p));}
 public Map<String,Object> payrollDetail(UUID id){var p=prepare("finance.payroll");var row=load("fb_payroll_batch",id,p,false);var out=external(row);out.put("lines",rows("select l.*,u.display_name as employee_name,(select coalesce(sum(fb_cash_effective_amount(p.tenant_id,'PAYROLL',p.id,p.amount,:asOf)),0) from fb_payroll_payment p where p.tenant_id=l.tenant_id and p.line_id=l.id) paid_amount from fb_payroll_line l join user_account u on u.tenant_id=l.tenant_id and u.id=l.employee_id where l.tenant_id=:tenantId and l.batch_id=:id order by u.display_name,l.id",base(p).addValue("id",id)));out.put("payments",rows("select p.* from fb_payroll_payment p join fb_payroll_line l on l.tenant_id=p.tenant_id and l.id=p.line_id where p.tenant_id=:tenantId and l.batch_id=:id",base(p).addValue("id",id)));out.put("attachments",attachments(p,"PAYROLL",id));audit.record("FINANCE_PAYROLL_VIEWED","FINANCE_PAYROLL",id,"{}");return out;}
 public Map<String,Object> createPayroll(PayrollBatch in){var p=prepare("finance.payroll");access.requirePermission("finance.submit");UUID company=company(p,in.hotelId());LocalDate month=month(in.month());account(p,in.reviewerId());account(p,in.cashierId());independent(p,in.reviewerId());independent(p,in.cashierId());if(replay(p,in.requestId(),in.requestId(),"PAYROLL_CREATE",in))return payrollDetail(in.requestId());
  if(in.supplementsId()!=null){var original=load("fb_payroll_batch",in.supplementsId(),p,true);if(!uid(original,"hotel_id").equals(in.hotelId())||!date(original,"month").equals(month)||!str(original,"status").equals("CONFIRMED"))throw bad("补发须关联同店同期间已确认工资批次，输入的是差异而非重发全额");}
  Set<UUID> employees=new HashSet<>();BigDecimal gross=BigDecimal.ZERO,deduction=BigDecimal.ZERO,employer=BigDecimal.ZERO;for(var line:in.lines()){if(!employees.add(line.employeeId()))throw bad("工资表员工重复");validateEmployee(p,line.employeeId(),line.departmentId(),in.hotelId(),month);BigDecimal g=components(line.earnings()),d=components(line.deductions()),e=components(line.employerCosts());if(g.compareTo(d)<0)throw bad("代扣不能超过应发工资");gross=gross.add(g);deduction=deduction.add(d);employer=employer.add(e);}if(gross.add(employer).signum()<=0)throw bad("无实际工资组件");
  jdbc.update("insert into fb_payroll_batch(id,tenant_id,hotel_id,company_id,month,source_reference,supplements_id,gross_amount,deduction_amount,net_amount,employer_amount,created_by,reviewer_id,cashier_id) values(:id,:tenantId,:hotel,:company,:month,:reference,:supplement,:gross,:deduction,:net,:employer,:actorId,:reviewer,:cashier)",base(p).addValue("id",in.requestId()).addValue("hotel",in.hotelId()).addValue("company",company).addValue("month",month).addValue("reference",in.sourceReference()).addValue("supplement",in.supplementsId()).addValue("gross",gross).addValue("deduction",deduction).addValue("net",gross.subtract(deduction)).addValue("employer",employer).addValue("reviewer",in.reviewerId()).addValue("cashier",in.cashierId()));
  for(var l:in.lines()){BigDecimal g=components(l.earnings()),d=components(l.deductions());jdbc.update("insert into fb_payroll_line(id,tenant_id,batch_id,employee_id,department_id,earnings,deductions,employer_costs,gross_amount,deduction_amount,net_amount,employer_amount) values(:id,:tenantId,:batch,:employee,:department,cast(:earnings as jsonb),cast(:deductions as jsonb),cast(:employerCosts as jsonb),:gross,:deduction,:net,:employer)",base(p).addValue("id",UUID.randomUUID()).addValue("batch",in.requestId()).addValue("employee",l.employeeId()).addValue("department",l.departmentId()).addValue("earnings",json(l.earnings())).addValue("deductions",json(l.deductions())).addValue("employerCosts",json(l.employerCosts())).addValue("gross",g).addValue("deduction",d).addValue("net",g.subtract(d)).addValue("employer",components(l.employerCosts())));}
  record(p,in.requestId(),in.requestId(),"PAYROLL_CREATE",in);notifyReview(p,"FINANCE_PAYROLL",in.requestId(),in.reviewerId(),0);return payrollDetail(in.requestId());
 }
 public Map<String,Object> confirmPayroll(UUID id,Confirm in){var p=prepare("finance.payroll");access.requirePermission("finance.review");if(replay(p,in.requestId(),id,"PAYROLL_CONFIRM",in))return payrollDetail(id);var row=load("fb_payroll_batch",id,p,true);version(row,in.expectedVersion());reviewer(p,row,"created_by","reviewer_id");if(!str(row,"status").equals("REVIEW"))throw conflict("工资已确认");requireOriginal(p,"PAYROLL",id);
  jdbc.update("update fb_payroll_batch set status='CONFIRMED',confirmed_by=:actorId,version=version+1 where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));
  for(var line:jdbc.queryForList("select * from fb_payroll_line where tenant_id=:tenantId and batch_id=:id",base(p).addValue("id",id))){for(String component:List.of("earnings","deductions","employer_costs")){var values=object(line.get(component));for(var e:values.entrySet()){BigDecimal amount=money(new BigDecimal(e.getValue().toString()));if(amount.signum()>0)event(p,row,"fb_payroll_batch","FB_PAYROLL",component.toUpperCase(Locale.ROOT)+":"+e.getKey(),amount,date(row,"month"),uid(line,"id"),Map.of("employeeId",str(line,"employee_id"),"departmentId",str(line,"department_id"),"payrollBatchId",id.toString()));}}}
  record(p,in.requestId(),id,"PAYROLL_CONFIRM",in);return payrollDetail(id);
 }
 public Map<String,Object> payPayroll(UUID id,PayrollPayment in){var p=prepare("finance.payroll");access.requirePermission("finance.pay");if(replay(p,in.requestId(),id,"PAYROLL_PAYMENT",in))return payrollDetail(id);var row=load("fb_payroll_batch",id,p,true);if(!str(row,"status").equals("CONFIRMED")||!p.actorId().equals(uid(row,"cashier_id"))||p.actorId().equals(uid(row,"created_by")))throw forbidden();var line=jdbc.queryForList("select * from fb_payroll_line where tenant_id=:tenantId and batch_id=:id and id=:line",base(p).addValue("id",id).addValue("line",in.lineId()));if(line.isEmpty())throw missing();positive(in.amount());BigDecimal paid=jdbc.queryForObject("select coalesce(sum(fb_cash_effective_amount(tenant_id,'PAYROLL',id,amount,:asOf)),0) from fb_payroll_payment where tenant_id=:tenantId and line_id=:line",base(p).addValue("line",in.lineId()),BigDecimal.class);if(paid.add(in.amount()).compareTo(dec(line.getFirst(),"net_amount"))>0)throw conflict("工资分次发放累计超过员工实发净额");
  jdbc.update("insert into fb_payroll_payment(id,tenant_id,line_id,amount,occurred_on,bank_reference,created_by) values(:id,:tenantId,:line,:amount,:day,:reference,:actorId)",base(p).addValue("id",in.requestId()).addValue("line",in.lineId()).addValue("amount",money(in.amount())).addValue("day",in.occurredOn()).addValue("reference",in.bankReference()));event(p,row,"fb_payroll_batch","FB_PAYROLL","PAYMENT",in.amount(),in.occurredOn(),in.requestId(),Map.of("employeeId",str(line.getFirst(),"employee_id")));record(p,in.requestId(),id,"PAYROLL_PAYMENT",in);return payrollDetail(id);
 }
 private BigDecimal components(Map<String,BigDecimal> values){if(values.size()>100)throw bad("工资组件过多");BigDecimal sum=BigDecimal.ZERO;for(var e:values.entrySet()){if(!e.getKey().matches("[A-Za-z0-9_-]{1,60}"))throw bad("工资组件应为1至60位稳定代码");nonnegative(e.getValue());sum=sum.add(e.getValue());}return money(sum);}
 private void validateEmployee(TenantPrincipal p,UUID employee,UUID department,UUID hotel,LocalDate payrollMonth){if(jdbc.queryForObject("select count(*) from user_account where tenant_id=:tenantId and id=:employee",base(p).addValue("employee",employee),Integer.class)!=1)throw bad("工资员工档案账号不存在");var b=base(p).addValue("employee",employee).addValue("hotel",hotel).addValue("start",payrollMonth).addValue("end",payrollMonth.plusMonths(1)).addValue("department",department);if(jdbc.queryForObject("select count(*) from employee_position_assignment a join employee e on e.tenant_id=a.tenant_id and e.id=a.employee_id where a.tenant_id=:tenantId and e.account_id=:employee and (a.status=\'ACTIVE\' or a.status=\'INACTIVE\' and a.valid_to is not null) and a.valid_from<:end and (a.valid_to is null or a.valid_to>=:start) and (a.org_unit_id=:hotel or exists(select 1 from org_unit_closure c where c.tenant_id=a.tenant_id and c.ancestor_id=:hotel and c.descendant_id=a.org_unit_id))",b,Integer.class)<1)throw bad("工资员工没有该工资期间的本店真实任职，不能用当前调店身份覆盖历史");if(jdbc.queryForObject("select count(*) from org_unit o where o.tenant_id=:tenantId and o.id=:department and (o.id=:hotel or exists(select 1 from org_unit_closure c where c.tenant_id=o.tenant_id and c.ancestor_id=:hotel and c.descendant_id=o.id))",b,Integer.class)!=1)throw bad("工资分摊部门不属于本店组织树");}

 public Map<String,Object> intercompanyList(){var p=prepare("finance.read","finance.review");return list("select d.* from fb_intercompany d where tenant_id=:tenantId and ("+scope("d")+" or :tenantScope or d.counterparty_hotel_id in (:scopeIds)) order by month desc,id",base(p));}
 public Map<String,Object> createIntercompany(Intercompany in){var p=prepare("finance.submit");UUID company=company(p,in.hotelId()),counterparty=company(p,in.counterpartyHotelId());if(in.hotelId().equals(in.counterpartyHotelId()))throw bad("往来双方不可为同一门店");account(p,in.reviewerId());account(p,in.counterpartyReviewerId());independent(p,in.reviewerId());independent(p,in.counterpartyReviewerId());if(in.reviewerId().equals(in.counterpartyReviewerId()))throw bad("双方必须独立确认");if(!Set.of("ADVANCE","SERVICE","ALLOCATION").contains(in.kind()))throw bad("往来性质未知");positive(in.amount());if(replay(p,in.requestId(),in.requestId(),"INTERCOMPANY_CREATE",in))return intercompanyDetail(in.requestId());
  BigDecimal total=in.basis().stream().map(Basis::weight).peek(FinanceBusinessService::positive).reduce(BigDecimal.ZERO,BigDecimal::add),allocated=BigDecimal.ZERO;var snapshot=new ArrayList<Map<String,Object>>();Set<String> keys=new HashSet<>();for(int i=0;i<in.basis().size();i++){var item=in.basis().get(i);if(!keys.add(item.key()))throw bad("分摊基数维度重复");BigDecimal amount=i==in.basis().size()-1?in.amount().subtract(allocated):in.amount().multiply(item.weight()).divide(total,2,RoundingMode.DOWN);allocated=allocated.add(amount);snapshot.add(Map.of("key",item.key(),"weight",item.weight().toPlainString(),"reference",item.reference(),"allocatedAmount",amount.toPlainString()));}
  jdbc.update("insert into fb_intercompany(id,tenant_id,hotel_id,company_id,counterparty_hotel_id,counterparty_company_id,month,kind,amount,basis_reference,basis_snapshot,creator_id,reviewer_id,counterparty_reviewer_id) values(:id,:tenantId,:hotel,:company,:counterHotel,:counterCompany,:month,:kind,:amount,:reference,cast(:basis as jsonb),:actorId,:reviewer,:counterReviewer)",base(p).addValue("id",in.requestId()).addValue("hotel",in.hotelId()).addValue("company",company).addValue("counterHotel",in.counterpartyHotelId()).addValue("counterCompany",counterparty).addValue("month",month(in.month())).addValue("kind",in.kind()).addValue("amount",money(in.amount())).addValue("reference",in.basisReference()).addValue("basis",json(snapshot)).addValue("reviewer",in.reviewerId()).addValue("counterReviewer",in.counterpartyReviewerId()));record(p,in.requestId(),in.requestId(),"INTERCOMPANY_CREATE",in);notifyReview(p,"FINANCE_INTERCOMPANY",in.requestId(),in.reviewerId(),0);notifyReview(p,"FINANCE_INTERCOMPANY",in.requestId(),in.counterpartyReviewerId(),0);return intercompanyDetail(in.requestId());
 }
 public Map<String,Object> intercompanyDetail(UUID id){var p=prepare("finance.read","finance.review","finance.submit","finance.pay");var row=bilateral(id,p,false);var out=external(row);var settlements=jdbc.queryForList("select *,fb_cash_effective_amount(tenant_id,'INTERCOMPANY',id,amount,:asOf) effective_amount from fb_intercompany_settlement where tenant_id=:tenantId and transaction_id=:id order by occurred_on,id",base(p).addValue("id",id));out.put("settlements",settlements.stream().map(this::external).toList());BigDecimal origin=settlements.stream().filter(v->"ORIGIN".equals(v.get("side"))).map(v->dec(v,"effective_amount")).reduce(BigDecimal.ZERO,BigDecimal::add),counter=settlements.stream().filter(v->"COUNTERPARTY".equals(v.get("side"))).map(v->dec(v,"effective_amount")).reduce(BigDecimal.ZERO,BigDecimal::add);out.put("originSettled",origin.toPlainString());out.put("counterpartySettled",counter.toPlainString());out.put("bilateralCashDifference",origin.subtract(counter).toPlainString());return out;}
 public Map<String,Object> settleIntercompany(UUID id,IntercompanySettlement in){var p=prepare("finance.pay");if(replay(p,in.requestId(),id,"INTERCOMPANY_SETTLEMENT",in))return intercompanyDetail(id);var row=bilateral(id,p,true);if(!str(row,"status").equals("CONFIRMED")||!Set.of("ORIGIN","COUNTERPARTY").contains(in.side()))throw conflict("须双方确认后分别登记各自真实收付");boolean counter=in.side().equals("COUNTERPARTY");UUID hotel=uid(row,counter?"counterparty_hotel_id":"hotel_id"),company=uid(row,counter?"counterparty_company_id":"company_id");access.requireOrgScope(hotel);var config=configuration(p,hotel);if(!p.actorId().equals(uid(config,"cashier_account_id"))||p.actorId().equals(uid(row,"creator_id")))throw forbidden();positive(in.amount());BigDecimal settled=jdbc.queryForObject("select coalesce(sum(fb_cash_effective_amount(tenant_id,'INTERCOMPANY',id,amount,:asOf)),0) from fb_intercompany_settlement where tenant_id=:tenantId and transaction_id=:id and side=:side",base(p).addValue("id",id).addValue("side",in.side()),BigDecimal.class);if(settled.add(in.amount()).compareTo(dec(row,"amount"))>0)throw conflict("本方资金结算不能超过已确认内部往来余额");if(in.occurredOn().isBefore(date(row,"month")))throw bad("内部结算不能早于确认期间");boolean advance=str(row,"kind").equals("ADVANCE");String kind=(counter!=advance)?"PAYMENT":"RECEIPT";
  jdbc.update("insert into fb_intercompany_settlement(id,tenant_id,transaction_id,hotel_id,company_id,side,kind,amount,occurred_on,bank_reference,created_by) values(:payment,:tenantId,:id,:hotel,:company,:side,:kind,:amount,:day,:reference,:actorId)",base(p).addValue("payment",in.requestId()).addValue("id",id).addValue("hotel",hotel).addValue("company",company).addValue("side",in.side()).addValue("kind",kind).addValue("amount",money(in.amount())).addValue("day",in.occurredOn()).addValue("reference",in.bankReference()));var fact=new LinkedHashMap<>(row);fact.put("hotel_id",hotel);fact.put("company_id",company);event(p,fact,"fb_intercompany","FB_INTERCOMPANY_CASH",kind,in.amount(),in.occurredOn(),in.requestId(),Map.of("side",in.side(),"transactionId",id.toString()));record(p,in.requestId(),id,"INTERCOMPANY_SETTLEMENT",in);return intercompanyDetail(id);
 }
 public Map<String,Object> confirmIntercompany(UUID id,Confirm in){var p=prepare("finance.review");if(replay(p,in.requestId(),id,"INTERCOMPANY_CONFIRM",in))return intercompanyDetail(id);var row=bilateral(id,p,true);version(row,in.expectedVersion());if(p.actorId().equals(uid(row,"creator_id")))throw forbidden();String column;
  if(!str(row,"status").equals("REVIEW"))throw conflict("内部往来已撤销或已完成确认，不可恢复旧节点");
  if(p.actorId().equals(uid(row,"reviewer_id"))){access.requireOrgScope(uid(row,"hotel_id"));column="confirmed_by";}else if(p.actorId().equals(uid(row,"counterparty_reviewer_id"))){access.requireOrgScope(uid(row,"counterparty_hotel_id"));column="counterparty_confirmed_by";}else throw forbidden();if(row.get(column)!=null)throw conflict("本方已确认");
  jdbc.update("update fb_intercompany set "+column+"=:actorId,version=version+1 where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));row=bilateral(id,p,true);if(row.get("confirmed_by")!=null&&row.get("counterparty_confirmed_by")!=null){jdbc.update("update fb_intercompany set status='CONFIRMED' where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));
   event(p,row,"fb_intercompany","FB_INTERCOMPANY",str(row,"kind")+"_ORIGIN",dec(row,"amount"),date(row,"month"),id,Map.of("side","ORIGIN","counterpartyHotelId",str(row,"counterparty_hotel_id")));
   var counter=new LinkedHashMap<>(row);counter.put("hotel_id",row.get("counterparty_hotel_id"));counter.put("company_id",row.get("counterparty_company_id"));event(p,counter,"fb_intercompany","FB_INTERCOMPANY",str(row,"kind")+"_COUNTERPARTY",dec(row,"amount"),date(row,"month"),id,Map.of("side","COUNTERPARTY","counterpartyHotelId",str(row,"hotel_id")));
  }record(p,in.requestId(),id,"INTERCOMPANY_CONFIRM",in);return intercompanyDetail(id);
 }
 private Map<String,Object> bilateral(UUID id,TenantPrincipal p,boolean locked){var values=jdbc.queryForList("select d.* from fb_intercompany d where tenant_id=:tenantId and id=:id and ("+scope("d")+" or :tenantScope or counterparty_hotel_id in (:scopeIds))"+(locked?" for update":""),base(p).addValue("id",id));if(values.isEmpty())throw missing();return values.getFirst();}
 public Map<String,Object> consolidationScopes(){var p=prepare("finance.accounting.read");var all=jdbc.queryForList("select * from fb_consolidation_scope where tenant_id=:tenantId order by name,version desc",base(p));return Map.of("items",all.stream().filter(r->uuidList(r.get("hotel_ids")).stream().allMatch(id->p.hasTenantScope()||p.orgScopes().contains(id))).map(this::external).toList());}
 public Map<String,Object> createScope(ConsolidationScope in){var p=prepare("finance.configure");if(replay(p,in.requestId(),in.requestId(),"CONSOLIDATION_SCOPE",in))return external(raw("fb_consolidation_scope",in.requestId(),p,false));for(UUID hotel:in.hotelIds())company(p,hotel);if(new HashSet<>(in.hotelIds()).size()!=in.hotelIds().size())throw bad("合并范围门店重复");for(var rule:in.rules())if(!Set.of("ADVANCE","SERVICE","ALLOCATION").contains(rule.transactionKind()))throw bad("抵销规则经济性质不支持");
  jdbc.update("insert into fb_consolidation_scope(id,tenant_id,name,version,hotel_ids,rules,created_by) values(:id,:tenantId,:name,:version,cast(:hotels as jsonb),cast(:rules as jsonb),:actorId)",base(p).addValue("id",in.requestId()).addValue("name",in.name()).addValue("version",in.version()).addValue("hotels",json(in.hotelIds())).addValue("rules",json(in.rules())));record(p,in.requestId(),in.requestId(),"CONSOLIDATION_SCOPE",in);return external(raw("fb_consolidation_scope",in.requestId(),p,false));
 }
 public Map<String,Object> publishScope(UUID id,Confirm in){var p=prepare("finance.configure");var row=raw("fb_consolidation_scope",id,p,true);for(UUID h:uuidList(row.get("hotel_ids")))access.requireOrgScope(h);if(p.actorId().equals(uid(row,"created_by")))throw forbidden();if(row.get("published_by")!=null)return external(row);jdbc.update("update fb_consolidation_scope set published_by=:actorId where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));audit.record("FINANCE_CONSOLIDATION_PUBLISHED","FINANCE_CONSOLIDATION",id,json(in));return external(raw("fb_consolidation_scope",id,p,false));}
 public Map<String,Object> worksheet(Worksheet in){var p=prepare("finance.accounting.read");var scope=raw("fb_consolidation_scope",in.scopeId(),p,false);if(scope.get("published_by")==null)throw conflict("合并范围尚未由独立配置人发布");List<UUID> hotels=uuidList(scope.get("hotel_ids"));for(UUID h:hotels)access.requireOrgScope(h);LocalDate month=month(in.month());var b=base(p).addValue("hotels",hotels).addValue("month",month).addValue("end",month.plusMonths(1));
  lock(p,"command:"+in.requestId());var replay=jdbc.queryForList("select * from fb_command where tenant_id=:tenantId and request_id=:request",base(p).addValue("request",in.requestId()));if(!replay.isEmpty()){var command=replay.getFirst();if(!"CONSOLIDATION_WORKSHEET".equals(str(command,"operation"))||!hash(in).equals(str(command,"request_hash")))throw conflict("请求编号已用于不同内容");return external(raw("fb_consolidation_worksheet",uid(command,"resource_id"),p,false));}
  var books=jdbc.queryForList("select b.id,b.hotel_id,p.status,exists(select 1 from fa_import_batch i where i.tenant_id=b.tenant_id and i.book_id=b.id) opening_confirmed from fa_book b left join fa_period p on p.tenant_id=b.tenant_id and p.book_id=b.id and p.month=:month where b.tenant_id=:tenantId and b.enabled and b.hotel_id in (:hotels)",b);boolean complete=books.size()==hotels.size()&&books.stream().allMatch(v->"CLOSED".equals(v.get("status"))&&Boolean.TRUE.equals(v.get("opening_confirmed")));
  b.addValue("payroll",has(p,"finance.payroll"));var rawLines=consolidationBalances(b);if(!has(p,"finance.payroll"))complete=false;
  var facts=jdbc.queryForList("select d.*,(select count(*) from fa_source_event e join fa_voucher v on v.tenant_id=e.tenant_id and v.id=e.voucher_id where e.tenant_id=d.tenant_id and e.source_type='FB_INTERCOMPANY' and e.metadata->>'businessId'=cast(d.id as text) and v.status='POSTED' and v.reversed_by_id is null) posted_sides from fb_intercompany d where d.tenant_id=:tenantId and d.month<:end and d.status='CONFIRMED' and d.hotel_id in (:hotels) and d.counterparty_hotel_id in (:hotels) order by d.id",b);
  var eliminations=new ArrayList<Map<String,Object>>();var adjusted=new LinkedHashMap<String,BigDecimal>();for(var line:rawLines)adjusted.merge(str(line,"report_line"),dec(line,"debit").subtract(dec(line,"credit")),BigDecimal::add);
  List<Map<String,Object>> rules=objects(scope.get("rules"));for(var fact:facts){var matches=rules.stream().filter(r->str(r,"transactionKind").equals(str(fact,"kind"))).toList();if(matches.isEmpty()||((Number)fact.get("posted_sides")).intValue()!=2){complete=false;eliminations.add(Map.of("transactionId",fact.get("id"),"status","PENDING_BILATERAL_POSTING_OR_RULE","amount",dec(fact,"amount").toPlainString()));continue;}
   var sourceLines=jdbc.queryForList("select a.report_line,sum(l.debit-l.credit) balance from fa_source_event e join fa_voucher v on v.tenant_id=e.tenant_id and v.id=e.voucher_id join fa_voucher_line l on l.tenant_id=v.tenant_id and l.voucher_id=v.id join fa_account a on a.tenant_id=l.tenant_id and a.id=l.account_id where e.tenant_id=:tenantId and ((e.source_type in ('FB_INTERCOMPANY','FB_INTERCOMPANY_CASH') and e.metadata->>'businessId'=:business) or (e.source_type='FB_CASH_CORRECTION_INTERCOMPANY' and e.metadata->>'transactionId'=:business)) and v.accounting_date<:end and (:sameMonth or a.category not in ('REVENUE','EXPENSE')) and not a.cash_account and v.status='POSTED' and v.reversed_by_id is null group by a.report_line",base(p).addValue("business",str(fact,"id")).addValue("end",month.plusMonths(1)).addValue("sameMonth",date(fact,"month").equals(month)));var remaining=new HashMap<String,BigDecimal>();sourceLines.forEach(line->remaining.put(str(line,"report_line"),dec(line,"balance")));
   for(var rule:matches){String debit=str(rule,"debitReportLine"),credit=str(rule,"creditReportLine");BigDecimal creditBalance=remaining.getOrDefault(debit,BigDecimal.ZERO),debitBalance=remaining.getOrDefault(credit,BigDecimal.ZERO);if(creditBalance.signum()==0&&debitBalance.signum()==0)continue;BigDecimal amount=creditBalance.negate().min(debitBalance);if(debit.equals(credit)||creditBalance.signum()>=0||debitBalance.signum()<=0||amount.signum()<=0){complete=false;eliminations.add(Map.of("transactionId",fact.get("id"),"status","PENDING_EXACT_SOURCE_LINE_MAPPING","debitReportLine",debit,"creditReportLine",credit));continue;}adjusted.merge(debit,amount,BigDecimal::add);adjusted.merge(credit,amount.negate(),BigDecimal::add);remaining.merge(debit,amount,BigDecimal::add);remaining.merge(credit,amount.negate(),BigDecimal::add);eliminations.add(Map.of("transactionId",fact.get("id"),"status","CALCULATED","debitReportLine",debit,"creditReportLine",credit,"amount",amount.toPlainString()));}
   if(remaining.values().stream().anyMatch(value->value.signum()!=0)){complete=false;eliminations.add(Map.of("transactionId",fact.get("id"),"status","PENDING_UNELIMINATED_INTERNAL_BALANCE","remaining",remaining));}
  }
  var snapshot=new LinkedHashMap<String,Object>();snapshot.put("scopeVersion",scope.get("version"));snapshot.put("month",in.month());snapshot.put("status",complete?"FINAL_WORKSHEET":"INCOMPLETE_WORKSHEET");snapshot.put("books",books);snapshot.put("aggregateLines",rawLines);snapshot.put("internalFacts",facts.stream().map(this::external).toList());snapshot.put("eliminations",eliminations);snapshot.put("adjustedLines",adjusted);snapshot.put("basis","人民币管理合并底稿：损益为当月发生，资产负债权益为确认期初加截至月末已过账；旧期内部未清继续抵销，实收付从双方未清扣除。不含复杂权益处理；未关账、期初未确认或未双边过账明确不完整");String sourceHash=hash(snapshot);
  lock(p,"worksheet:"+in.scopeId()+in.month());var existing=jdbc.queryForList("select * from fb_consolidation_worksheet where tenant_id=:tenantId and scope_id=:scope and month=:month and source_hash=:hash",b.addValue("scope",in.scopeId()).addValue("hash",sourceHash));if(!existing.isEmpty()){var previous=existing.getFirst();record(p,in.requestId(),uid(previous,"id"),"CONSOLIDATION_WORKSHEET",in);return external(previous);}
  jdbc.update("insert into fb_consolidation_worksheet(id,tenant_id,scope_id,month,source_hash,snapshot,created_by) values(:id,:tenantId,:scope,:month,:hash,cast(:snapshot as jsonb),:actorId)",b.addValue("id",in.requestId()).addValue("scope",in.scopeId()).addValue("hash",sourceHash).addValue("snapshot",json(snapshot)));record(p,in.requestId(),in.requestId(),"CONSOLIDATION_WORKSHEET",in);return external(raw("fb_consolidation_worksheet",in.requestId(),p,false));
 }

 public Map<String,Object> outputRequests(){var p=prepare("finance.tax");return list("select d.*,(select sum(amount) from fb_output_line l where l.tenant_id=d.tenant_id and l.request_id=d.id) amount from fb_output_request d where tenant_id=:tenantId and "+scope("d")+" order by created_at desc,id",base(p));}
 public Map<String,Object> outputDetail(UUID id){var p=prepare("finance.tax");var out=external(load("fb_output_request",id,p,false));out.put("lines",rows("select * from fb_output_line where tenant_id=:tenantId and request_id=:id",base(p).addValue("id",id)));out.put("invoices",rows("select * from fb_output_invoice where tenant_id=:tenantId and request_id=:id order by created_at,id",base(p).addValue("id",id)));out.put("attachments",attachments(p,"OUTPUT",id));return out;}
 public Map<String,Object> createOutput(OutputRequest in){var p=prepare("finance.tax");UUID company=company(p,in.hotelId());if(replay(p,in.requestId(),in.requestId(),"OUTPUT_REQUEST",in))return outputDetail(in.requestId());Set<UUID> seen=new HashSet<>();
  for(var l:in.lines().stream().sorted(Comparator.comparing(InvoiceAllocation::entryId)).toList()){if(!seen.add(l.entryId()))throw bad("开票来源行重复");positive(l.amount());var row=load("fb_revenue_entry",l.entryId(),p,true);if(!uid(row,"hotel_id").equals(in.hotelId())||!uid(row,"company_id").equals(company)||!Boolean.TRUE.equals(row.get("active"))||!Set.of("INCOME","AR").contains(str(row,"kind")))throw bad("仅可关联同主体当前已确认营业收入/应收，押金预收不可直接开收入票");
   BigDecimal reserved=reservedInvoiceAmount(p,row);if(reserved.add(l.amount()).compareTo(dec(row,"amount"))>0)throw conflict("累计开票/排队额度超过收入（含历次重结），避免重复开票");}
  jdbc.update("insert into fb_output_request(id,tenant_id,hotel_id,company_id,buyer_name,buyer_tax_number,created_by) values(:id,:tenantId,:hotel,:company,:buyer,:tax,:actorId)",base(p).addValue("id",in.requestId()).addValue("hotel",in.hotelId()).addValue("company",company).addValue("buyer",in.buyerName()).addValue("tax",in.buyerTaxNumber()));for(var l:in.lines())jdbc.update("insert into fb_output_line(tenant_id,request_id,entry_id,amount) values(:tenantId,:id,:entry,:amount)",base(p).addValue("id",in.requestId()).addValue("entry",l.entryId()).addValue("amount",money(l.amount())));record(p,in.requestId(),in.requestId(),"OUTPUT_REQUEST",in);return outputDetail(in.requestId());
 }
 public Map<String,Object> cancelOutput(UUID id,Confirm in){var p=prepare("finance.tax");if(replay(p,in.requestId(),id,"OUTPUT_CANCEL",in))return outputDetail(id);var row=load("fb_output_request",id,p,true);version(row,in.expectedVersion());BigDecimal net=jdbc.queryForObject("select coalesce(sum((case when red_of is null then 1 else -1 end)*(net_amount+tax_amount)),0) from fb_output_invoice where tenant_id=:tenantId and request_id=:id",base(p).addValue("id",id),BigDecimal.class);if(str(row,"status").equals("CANCELLED")||net.signum()!=0)throw conflict("仍有未红冲实际发票，不能撤销请求释放额度；请先完成真实全额红冲");jdbc.update("update fb_output_request set status='CANCELLED',version=version+1 where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));record(p,in.requestId(),id,"OUTPUT_CANCEL",in);return outputDetail(id);}
 public Map<String,Object> executeInvoice(UUID id){var p=prepare("finance.tax");load("fb_output_request",id,p,false);throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"未配置并授权真实外部开票连接，不会执行；可上传真实发票登记外部结果，重试前须查原外部请求号");}
 public Map<String,Object> registerInvoice(UUID id,InvoiceResult in){var p=prepare("finance.tax");if(replay(p,in.requestId(),id,"OUTPUT_REGISTER",in))return outputDetail(id);var request=load("fb_output_request",id,p,true);version(request,in.expectedVersion());if(str(request,"status").equals("CANCELLED"))throw conflict("请求已撤销");nonnegative(in.netAmount());nonnegative(in.taxAmount());BigDecimal gross=money(in.netAmount()).add(money(in.taxAmount()));positive(gross);requireAttachment(p,"OUTPUT",id,in.attachmentId());
  lock(p,"invoice:"+in.invoiceCode().trim()+":"+in.invoiceNumber().trim());if(jdbc.queryForObject("select count(*) from fb_output_invoice where tenant_id=:tenantId and invoice_code=:code and invoice_number=:number",base(p).addValue("code",in.invoiceCode().trim()).addValue("number",in.invoiceNumber().trim()),Integer.class)>0)throw conflict("该实际销项发票号已归档，已阻止重复登记");
  BigDecimal total=jdbc.queryForObject("select sum(amount) from fb_output_line where tenant_id=:tenantId and request_id=:id",base(p).addValue("id",id),BigDecimal.class);BigDecimal current=jdbc.queryForObject("select coalesce(sum((case when red_of is null then 1 else -1 end)*(net_amount+tax_amount)),0) from fb_output_invoice where tenant_id=:tenantId and request_id=:id",base(p).addValue("id",id),BigDecimal.class);
  if(in.redOf()==null&&current.add(gross).compareTo(total)>0)throw conflict("分次登记发票累计超过排队金额");if(in.redOf()!=null){var original=raw("fb_output_invoice",in.redOf(),p,false);if(!id.equals(uid(original,"request_id"))||uid(original,"red_of")!=null)throw bad("红冲须关联本请求的实际蓝字票");var reds=jdbc.queryForMap("select coalesce(sum(net_amount),0) net_amount,coalesce(sum(tax_amount),0) tax_amount from fb_output_invoice where tenant_id=:tenantId and red_of=:original",base(p).addValue("original",in.redOf()));if(dec(reds,"net_amount").add(in.netAmount()).compareTo(dec(original,"net_amount"))>0||dec(reds,"tax_amount").add(in.taxAmount()).compareTo(dec(original,"tax_amount"))>0)throw conflict("红字净额/税额分别不得超过原票未红冲额");}
  jdbc.update("insert into fb_output_invoice(id,tenant_id,request_id,invoice_code,invoice_number,net_amount,tax_amount,issued_on,red_of,attachment_id,external_reference,created_by) values(:invoice,:tenantId,:id,:code,:number,:net,:tax,:day,:red,:attachment,:reference,:actorId)",base(p).addValue("invoice",in.requestId()).addValue("id",id).addValue("code",in.invoiceCode().trim()).addValue("number",in.invoiceNumber().trim()).addValue("net",money(in.netAmount())).addValue("tax",money(in.taxAmount())).addValue("day",in.issuedOn()).addValue("red",in.redOf()).addValue("attachment",in.attachmentId()).addValue("reference",in.externalReference()));
  jdbc.update("update fb_output_request set status='REGISTERED',version=version+1 where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));record(p,in.requestId(),id,"OUTPUT_REGISTER",in);return outputDetail(id);
 }
 public Map<String,Object> taxPolicies(){var p=prepare("finance.tax");return list("select d.* from fb_tax_policy d where tenant_id=:tenantId and "+scope("d")+" order by name,version desc",base(p));}
 public Map<String,Object> createTaxPolicy(TaxPolicy in){var p=prepare("finance.tax");access.requirePermission("finance.configure");UUID company=company(p,in.hotelId());if(in.effectiveUntil().isBefore(in.effectiveFrom()))throw bad("政策生效期错误");if(replay(p,in.requestId(),in.requestId(),"TAX_POLICY",in))return external(load("fb_tax_policy",in.requestId(),p,false));Set<String> codes=new HashSet<>();for(var field:in.fields()){if(!codes.add(field.code())||!TAX_SOURCES.contains(field.source())||field.factor().abs().compareTo(new BigDecimal("100"))>0||field.factor().scale()>8)throw bad("取数模板字段重复、来源未知或系数无效");}
  jdbc.update("insert into fb_tax_policy(id,tenant_id,hotel_id,company_id,name,version,effective_from,effective_until,official_reference,fields,created_by) values(:id,:tenantId,:hotel,:company,:name,:version,:start,:end,:reference,cast(:fields as jsonb),:actorId)",base(p).addValue("id",in.requestId()).addValue("hotel",in.hotelId()).addValue("company",company).addValue("name",in.name()).addValue("version",in.version()).addValue("start",in.effectiveFrom()).addValue("end",in.effectiveUntil()).addValue("reference",in.officialReference()).addValue("fields",json(in.fields())));record(p,in.requestId(),in.requestId(),"TAX_POLICY",in);return external(load("fb_tax_policy",in.requestId(),p,false));
 }
 public Map<String,Object> publishTaxPolicy(UUID id,Confirm in){var p=prepare("finance.tax");access.requirePermission("finance.configure");var row=load("fb_tax_policy",id,p,true);if(p.actorId().equals(uid(row,"created_by")))throw forbidden();jdbc.update("update fb_tax_policy set published_by=coalesce(published_by,:actorId) where tenant_id=:tenantId and id=:id",base(p).addValue("id",id));audit.record("FINANCE_TAX_POLICY_PUBLISHED","FINANCE_TAX_POLICY",id,json(in));return external(load("fb_tax_policy",id,p,false));}
 public Map<String,Object> inputTaxes(){var p=prepare("finance.tax");return list("select d.* from fb_input_tax d where tenant_id=:tenantId and "+scope("d")+" order by month desc,id",base(p));}
 public Map<String,Object> recordInputTax(InputTax in){var p=prepare("finance.tax");var typed=new FinanceInputTaxService(jdbc,db,access,audit,accounting);if(typed.installed())return typed.legacy(in);UUID company=company(p,in.hotelId());var policy=load("fb_tax_policy",in.policyId(),p,false);policyEffective(policy,company,month(in.month()));nonnegative(in.eligibleTax());nonnegative(in.claimedTax());nonnegative(in.transferOut());if(in.claimedTax().compareTo(in.eligibleTax())>0)throw bad("本期抵扣超过财务确认可抵扣税额");if(replay(p,in.requestId(),in.requestId(),"INPUT_TAX",in))return external(load("fb_input_tax",in.requestId(),p,false));
  // Only a confirmed original invoice owned by the same legal entity is eligible; an arbitrary UUID is not evidence.
  var invoices=jdbc.queryForList("select i.*,c.hotel_id,c.company_id from finance_invoice i join finance_claim c on c.tenant_id=i.tenant_id and c.id=i.claim_id where i.tenant_id=:tenantId and i.id=:invoice and c.hotel_id=:hotel and c.company_id=:company and c.status in ('APPROVED','PAID') and i.confirmed",base(p).addValue("invoice",in.invoiceId()).addValue("hotel",in.hotelId()).addValue("company",company));if(invoices.isEmpty())throw bad("进项须为同主体已批准报销的已确认真实发票；不以人工UUID代替发票资料");if(in.eligibleTax().compareTo(dec(invoices.getFirst(),"amount"))>0)throw bad("财务确认税额不能超过原票含税金额");
  lock(p,"input:"+in.invoiceId());var ceilings=jdbc.queryForList("select distinct eligible_tax from fb_input_tax where tenant_id=:tenantId and invoice_id=:invoice",base(p).addValue("invoice",in.invoiceId()));if(ceilings.stream().anyMatch(r->dec(r,"eligible_tax").compareTo(in.eligibleTax())!=0))throw conflict("原票可抵扣额已经冻结，不得通过新记录抬高上限；需专门政策调整复核");BigDecimal available=jdbc.queryForObject("select coalesce(sum(claimed_tax-transfer_out),0) from fb_input_tax where tenant_id=:tenantId and invoice_id=:invoice",base(p).addValue("invoice",in.invoiceId()),BigDecimal.class);if(in.transferOut().compareTo(available.add(in.claimedTax()))>0)throw conflict("累计转出超过已确认抵扣余额");if(available.add(in.claimedTax()).subtract(in.transferOut()).compareTo(in.eligibleTax())>0)throw conflict("累计抵扣超过该票财务确认税额");
  jdbc.update("insert into fb_input_tax(id,tenant_id,hotel_id,company_id,invoice_id,month,purpose,eligible_tax,claimed_tax,transfer_out,policy_id,note,created_by) values(:id,:tenantId,:hotel,:company,:invoice,:month,:purpose,:eligible,:claimed,:transfer,:policy,:note,:actorId)",base(p).addValue("id",in.requestId()).addValue("hotel",in.hotelId()).addValue("company",company).addValue("invoice",in.invoiceId()).addValue("month",month(in.month())).addValue("purpose",in.purpose()).addValue("eligible",money(in.eligibleTax())).addValue("claimed",money(in.claimedTax())).addValue("transfer",money(in.transferOut())).addValue("policy",in.policyId()).addValue("note",in.note()));var row=load("fb_input_tax",in.requestId(),p,false);if(in.claimedTax().signum()>0)event(p,row,"fb_input_tax","FB_INPUT_TAX","DEDUCTION",in.claimedTax(),month(in.month()),in.requestId(),Map.of("invoiceId",in.invoiceId().toString()));if(in.transferOut().signum()>0)event(p,row,"fb_input_tax","FB_INPUT_TAX","TRANSFER_OUT",in.transferOut(),month(in.month()),in.requestId(),Map.of("invoiceId",in.invoiceId().toString()));record(p,in.requestId(),in.requestId(),"INPUT_TAX",in);return external(row);
 }
 public Map<String,Object> taxReturns(){var p=prepare("finance.tax");var selected=jdbc.queryForList("select d.* from fb_tax_return d where tenant_id=:tenantId and "+scope("d")+" order by month desc,id",base(p));for(var row:selected)FinanceTaxScope.frozen(jdbc,access,p,row);return Map.of("items",selected.stream().map(this::external).toList(),"total",selected.size());}
 public Map<String,Object> taxReturnDetail(UUID id){var p=prepare("finance.tax");var row=load("fb_tax_return",id,p,false);var out=external(row);out.put("receipts",rows("select * from fb_tax_receipt where tenant_id=:tenantId and return_id=:id order by created_at,id",base(p).addValue("id",id)));out.put("attachments",attachments(p,"TAX",id));return out;}
 public Map<String,Object> createTaxReturn(TaxReturn in){var p=prepare("finance.tax");UUID company=company(p,in.hotelId());LocalDate month=month(in.month());var policy=load("fb_tax_policy",in.policyId(),p,false);policyEffective(policy,company,month);if(replay(p,in.requestId(),in.requestId(),"TAX_RETURN",in))return taxReturnDetail(in.requestId());if(!in.hotelId().equals(uid(policy,"hotel_id")))throw conflict("税务政策必须属于当前明确选择的组织，不能跨组织套用同法人政策");var b=base(p).addValue("company",company).addValue("month",month).addValue("end",month.plusMonths(1));if(jdbc.queryForObject("select count(*) from finance_store_config c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id where c.tenant_id=:tenantId and c.company_id=:company and c.enabled and c.workflow_version=2 and h.status=\'ACTIVE\' and not (:tenantScope or c.hotel_id in (:scopeIds))",b,Integer.class)>0)throw conflict("法人整期取数须覆盖同法人全部启用组织的真实权限，不能把未授权组织当零或自动扩大权限");requireTaxCompanySourceScope(p,company);jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,69))",Map.of("key",p.tenantId()+":invoice-registry"));var values=new LinkedHashMap<String,BigDecimal>();
  var output=jdbc.queryForMap("select coalesce(sum((case when i.red_of is null then 1 else -1 end)*i.net_amount),0) net,coalesce(sum((case when i.red_of is null then 1 else -1 end)*i.tax_amount),0) tax from fb_output_invoice i join fb_output_request q on q.tenant_id=i.tenant_id and q.id=i.request_id where i.tenant_id=:tenantId and q.company_id=:company and i.issued_on>=:month and i.issued_on<:end",b);values.put("OUTPUT_NET",dec(output,"net"));values.put("OUTPUT_TAX",dec(output,"tax"));
  var input=jdbc.queryForMap("select coalesce(sum(claimed_tax),0) claimed,coalesce(sum(transfer_out),0) transfer from fb_input_tax where tenant_id=:tenantId and company_id=:company and month=:month",b);values.put("INPUT_CLAIMED",dec(input,"claimed"));values.put("INPUT_TRANSFER_OUT",dec(input,"transfer"));
  var income=jdbc.queryForMap("select coalesce(sum(e.net_amount),0) net,coalesce(sum(e.tax_amount),0) tax from fb_revenue_entry e join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id where e.tenant_id=:tenantId and e.company_id=:company and e.active and e.kind in ('INCOME','AR') and b.business_date>=:month and b.business_date<:end",b);values.put("INCOME_NET",dec(income,"net"));values.put("INCOME_TAX",dec(income,"tax"));
  var ledger=jdbc.queryForMap("select coalesce(sum(l.debit),0) debit,coalesce(sum(l.credit),0) credit from fa_voucher v join fa_book b on b.tenant_id=v.tenant_id and b.id=v.book_id join fa_voucher_line l on l.tenant_id=v.tenant_id and l.voucher_id=v.id where v.tenant_id=:tenantId and b.company_id=:company and v.month=:month and v.status='POSTED'",b);values.put("POSTED_DEBIT",dec(ledger,"debit"));values.put("POSTED_CREDIT",dec(ledger,"credit"));
  var fields=new ArrayList<Map<String,Object>>();for(var f:objects(policy.get("fields"))){BigDecimal source=values.get(str(f,"source")),factor=new BigDecimal(f.get("factor").toString());fields.add(Map.of("code",f.get("code"),"label",f.get("label"),"source",f.get("source"),"sourceAmount",source.toPlainString(),"factor",factor.toPlainString(),"amount",source.multiply(factor).setScale(2,RoundingMode.HALF_UP).toPlainString()));}
  var snapshot=new LinkedHashMap<String,Object>();snapshot.put("policyId",in.policyId());snapshot.put("policyVersion",policy.get("version"));snapshot.put("officialReference",policy.get("official_reference"));snapshot.put("sources",values);snapshot.put("inputTaxSources",taxInputSources(p,company,month));snapshot.put("inputTaxBases",taxInputBases(p,company,month));snapshot.put("inputLineage","CAPTURED_AT_PREPARATION");snapshot.put("companyScopeVersion","FROZEN_COMPANY_HOTELS_V1");snapshot.put("companyScopeHotelIds",FinanceTaxScope.companyHotels(jdbc,p,company));snapshot.put("fields",fields);snapshot.put("invoiceIncomeDifference",values.get("OUTPUT_NET").subtract(values.get("INCOME_NET")).toPlainString());snapshot.put("declaredAmount",in.declaredAmount());snapshot.put("explanation",Objects.toString(in.explanation(),""));snapshot.put("status","PREPARATION_NOT_EXTERNALLY_FILED");snapshot.put("basis","已确认票据/来源及已过账总额的取数底稿；申报口径差异需人工说明，不自动申报");
  if(in.declaredAmount()!=null&&str(snapshot,"explanation").isBlank())throw bad("登记申报金额必须解释与取数口径的关系");
  jdbc.update("insert into fb_tax_return(id,tenant_id,hotel_id,company_id,month,policy_id,source_hash,snapshot,declared_amount,explanation,created_by) values(:id,:tenantId,:hotel,:company,:month,:policy,:hash,cast(:snapshot as jsonb),:declared,:explanation,:actorId)",b.addValue("id",in.requestId()).addValue("hotel",in.hotelId()).addValue("policy",in.policyId()).addValue("hash",hash(snapshot)).addValue("snapshot",json(snapshot)).addValue("declared",in.declaredAmount()).addValue("explanation",Objects.toString(in.explanation(),"")));record(p,in.requestId(),in.requestId(),"TAX_RETURN",in);return taxReturnDetail(in.requestId());
 }
 private void requireTaxCompanySourceScope(TenantPrincipal p,UUID company){String sources="select hotel_id from fa_book where tenant_id=:tenantId and company_id=:company union select hotel_id from fb_input_tax where tenant_id=:tenantId and company_id=:company union select q.hotel_id from fb_output_request q join fb_output_invoice i on i.tenant_id=q.tenant_id and i.request_id=q.id where q.tenant_id=:tenantId and q.company_id=:company union select hotel_id from fb_revenue_entry where tenant_id=:tenantId and company_id=:company";if(exists("ft_input_basis"))sources+=" union select hotel_id from ft_input_basis where tenant_id=:tenantId and company_id=:company";if(jdbc.queryForObject("select count(*) from ("+sources+") actual where not (:tenantScope or actual.hotel_id in (:scopeIds))",base(p).addValue("company",company),Integer.class)>0)throw conflict("法人实际来源及全部历史账套包含未授权组织；即使门店或账套停用也不能当零、排除历史或扩大权限，请取得真实法人完整范围后重新取数");}
 private List<Map<String,Object>> taxInputSources(TenantPrincipal p,UUID company,LocalDate period){var b=base(p).addValue("company",company).addValue("month",period);String sql=exists("ft_input_basis")?"select x.*,coalesce(t.source_parent_id,i.claim_id) source_parent_id from fb_input_tax x left join ft_input_basis t on t.tenant_id=x.tenant_id and t.id=x.basis_id and t.invoice_id=x.invoice_id and t.source_kind=x.source_kind left join finance_invoice i on i.tenant_id=x.tenant_id and i.id=x.invoice_id and x.source_kind='CLAIM' where x.tenant_id=:tenantId and x.company_id=:company and x.month=:month order by x.created_at,x.id":"select x.*,'CLAIM' source_kind,i.claim_id source_parent_id from fb_input_tax x left join finance_invoice i on i.tenant_id=x.tenant_id and i.id=x.invoice_id where x.tenant_id=:tenantId and x.company_id=:company and x.month=:month order by x.created_at,x.id";return jdbc.queryForList(sql,b).stream().map(FinanceV2Support::output).toList();}
 private List<Map<String,Object>> taxInputBases(TenantPrincipal p,UUID company,LocalDate period){if(!exists("ft_input_basis"))return List.of();return jdbc.queryForList("select t.* from ft_input_basis t where t.tenant_id=:tenantId and t.company_id=:company and t.status='CONFIRMED' and (exists(select 1 from fb_input_tax x where x.tenant_id=t.tenant_id and x.company_id=t.company_id and x.month=:month and x.basis_id=t.id) or exists(select 1 from fb_input_tax x where x.tenant_id=t.tenant_id and x.company_id=t.company_id and x.month=:month and x.basis_id=t.red_of_basis_id)) order by t.created_at,t.id",base(p).addValue("company",company).addValue("month",period)).stream().map(FinanceV2Support::output).toList();}
 public Map<String,Object> recordTaxReceipt(UUID id,TaxReceipt in){var p=prepare("finance.tax");if(replay(p,in.requestId(),id,"TAX_RECEIPT",in))return taxReturnDetail(id);lock(p,"tax-return:"+id);load("fb_tax_return",id,p,false);if(!Set.of("FILING","PAYMENT").contains(in.kind()))throw bad("回执类型未知");nonnegative(in.amount());requireAttachment(p,"TAX",id,in.attachmentId());if(in.kind().equals("PAYMENT")){var b=base(p).addValue("id",id);BigDecimal filed=jdbc.queryForObject("select coalesce(sum(amount),0) from fb_tax_receipt where tenant_id=:tenantId and return_id=:id and kind='FILING'",b,BigDecimal.class),paid=jdbc.queryForObject("select coalesce(sum(amount),0) from fb_tax_receipt where tenant_id=:tenantId and return_id=:id and kind='PAYMENT'",b,BigDecimal.class);if(paid.add(in.amount()).compareTo(filed)>0)throw conflict("完税金额超过已归档申报应缴额；先归档实际申报结果");}
  else if(jdbc.queryForObject("select count(*) from fb_tax_receipt where tenant_id=:tenantId and return_id=:id and kind='FILING'",base(p).addValue("id",id),Integer.class)>0)throw conflict("已归档申报结果，修订须保留新的取数/申报版本，不能累加冒充同次申报");
  jdbc.update("insert into fb_tax_receipt(id,tenant_id,return_id,kind,external_reference,amount,attachment_id,occurred_on,created_by) values(:receipt,:tenantId,:id,:kind,:reference,:amount,:attachment,:day,:actorId)",base(p).addValue("receipt",in.requestId()).addValue("id",id).addValue("kind",in.kind()).addValue("reference",in.externalReference()).addValue("amount",money(in.amount())).addValue("attachment",in.attachmentId()).addValue("day",in.occurredOn()));record(p,in.requestId(),id,"TAX_RECEIPT",in);return taxReturnDetail(id);
 }
 private void policyEffective(Map<String,Object> policy,UUID company,LocalDate month){if(!company.equals(uid(policy,"company_id"))||policy.get("published_by")==null||month.isBefore(date(policy,"effective_from"))||month.isAfter(date(policy,"effective_until")))throw conflict("政策未发布、主体不同或不在生效期间");}

 public Map<String,Object> cashFacts(){var p=prepare("finance.read","finance.pay","finance.review");String sql="select m.id,'REVENUE' source_type,e.hotel_id,e.customer title,m.amount,m.occurred_on,m.bank_reference,case when m.kind='RECEIPT' then 'IN' else 'OUT' end direction from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id where m.tenant_id=:tenantId and m.kind in ('RECEIPT','REFUND') and "+scope("e");
  sql+=" union all select c.id,'OPENING' source_type,c.hotel_id,'迁移期初未清收付' title,c.amount,c.occurred_on,c.bank_reference,case when c.kind='RECEIPT' then 'IN' else 'OUT' end direction from fb_opening_clearing c where c.tenant_id=:tenantId and "+scope("c");
  sql+=" union all select c.id,'INTERCOMPANY' source_type,c.hotel_id,'双边实际收付' title,c.amount,c.occurred_on,c.bank_reference,case when c.kind='RECEIPT' then 'IN' else 'OUT' end direction from fb_intercompany_settlement c where c.tenant_id=:tenantId and "+scope("c");
  if(exists("ft_tax_payment")&&has(p,"finance.tax"))sql+=" union all select t.id,\'TAX\' source_type,t.hotel_id,\'真实税款清偿\' title,t.amount,t.occurred_on,b.external_id bank_reference,\'OUT\' direction from ft_tax_payment t join fo_bank_transaction b on b.tenant_id=t.tenant_id and b.id=t.bank_transaction_id where t.tenant_id=:tenantId and "+scope("t");
  if(has(p,"finance.payroll"))sql+=" union all select y.id,'PAYROLL' source_type,b.hotel_id,'工资发放' title,y.amount,y.occurred_on,y.bank_reference,'OUT' direction from fb_payroll_payment y join fb_payroll_line l on l.tenant_id=y.tenant_id and l.id=y.line_id join fb_payroll_batch b on b.tenant_id=l.tenant_id and b.id=l.batch_id where y.tenant_id=:tenantId and "+scope("b");var facts=jdbc.queryForList(sql+" order by occurred_on,id",base(p));var results=new ArrayList<Map<String,Object>>();for(var row:facts){var out=external(row);BigDecimal matched=matchedCash(p,str(row,"source_type"),uid(row,"id")),effective=effectiveCash(p,str(row,"source_type"),uid(row,"id"),dec(row,"amount"));out.put("correctedAmount",dec(row,"amount").subtract(effective).toPlainString());out.put("effectiveAmount",effective.toPlainString());out.put("matchedAmount",matched.toPlainString());out.put("unmatchedAmount",effective.subtract(matched).toPlainString());out.put("reconciliationStatus",effective.signum()==0?"CORRECTED":matched.compareTo(effective)==0?"MATCHED":"UNMATCHED");results.add(out);}return Map.of("items",results,"total",results.size(),"unmatchedCount",results.stream().filter(r->"UNMATCHED".equals(r.get("reconciliationStatus"))).count());
 }
 public Map<String,Object> bankMatches(){var p=prepare("finance.read","finance.pay","finance.review");var rows=jdbc.queryForList("select m.*,m.amount-coalesce((select sum(r.amount) from fb_bank_match_reversal r where r.tenant_id=m.tenant_id and r.match_id=m.id and r.accounting_on<=:asOf),0) effective_amount,b.hotel_id,t.external_id from fb_bank_match m join fo_bank_transaction t on t.tenant_id=m.tenant_id and t.id=m.transaction_id join fo_bank_account b on b.tenant_id=t.tenant_id and b.id=t.bank_account_id where m.tenant_id=:tenantId and "+scope("b")+" and (:payroll or m.source_type<>'PAYROLL') and (:tax or m.source_type<>'TAX') order by m.created_at,m.id",base(p).addValue("payroll",has(p,"finance.payroll")).addValue("tax",has(p,"finance.tax")));return Map.of("items",rows.stream().map(this::external).toList(),"total",rows.size());}
 public Map<String,Object> bankMatchSuggestions(){var p=prepare("finance.read","finance.pay","finance.review");var banks=jdbc.queryForList("select t.*,b.hotel_id from fo_bank_transaction t join fo_bank_account b on b.tenant_id=t.tenant_id and b.id=t.bank_account_id where t.tenant_id=:tenantId and "+scope("b")+" order by t.occurred_on desc,t.id limit 201",base(p));@SuppressWarnings("unchecked") var facts=(List<Map<String,Object>>)cashFacts().get("items");var result=new ArrayList<Map<String,Object>>();boolean complete=banks.size()<=200&&facts.size()<=2000;for(var bank:banks.stream().limit(200).toList()){BigDecimal remaining=dec(bank,"amount").subtract(bankAllocated(p,uid(bank,"id")));if(remaining.signum()<=0)continue;var candidates=new ArrayList<Map<String,Object>>();for(var fact:facts.stream().limit(2000).toList()){BigDecimal sourceRemaining=new BigDecimal(fact.get("unmatchedAmount").toString());if(sourceRemaining.signum()<=0||!bank.get("hotel_id").equals(fact.get("hotelId"))||!bank.get("direction").equals(fact.get("direction")))continue;boolean referenceMatch=!str(bank,"reference").isBlank()&&str(bank,"reference").trim().equalsIgnoreCase(Objects.toString(fact.get("bankReference"),"").trim())||str(bank,"external_id").equals(Objects.toString(fact.get("bankReference"),""));long dayDistance=Math.abs(java.time.temporal.ChronoUnit.DAYS.between(date(bank,"occurred_on"),LocalDate.parse(fact.get("occurredOn").toString())));var candidate=new LinkedHashMap<String,Object>();candidate.put("transactionId",bank.get("id"));candidate.put("externalId",bank.get("external_id"));candidate.put("sourceType",fact.get("sourceType"));candidate.put("sourceId",fact.get("id"));candidate.put("sourceTitle",fact.get("title"));candidate.put("bankRemaining",remaining.toPlainString());candidate.put("sourceRemaining",sourceRemaining.toPlainString());candidate.put("proposedAmount",remaining.min(sourceRemaining).toPlainString());candidate.put("referenceMatch",referenceMatch);candidate.put("dayDistance",dayDistance);candidate.put("amountEqual",remaining.compareTo(sourceRemaining)==0);candidate.put("suggestionOnly",true);candidates.add(candidate);}candidates.sort(Comparator.<Map<String,Object>,Boolean>comparing(v->!Boolean.TRUE.equals(v.get("referenceMatch"))).thenComparing(v->!Boolean.TRUE.equals(v.get("amountEqual"))).thenComparingLong(v->((Number)v.get("dayDistance")).longValue()).thenComparing(v->v.get("sourceId").toString()));int count=candidates.size();for(var candidate:candidates.stream().limit(20).toList()){candidate.put("candidateCount",count);candidate.put("ambiguous",count!=1);result.add(candidate);}if(count>20)complete=false;if(count==0)result.add(Map.of("transactionId",bank.get("id"),"externalId",bank.get("external_id"),"bankRemaining",remaining.toPlainString(),"candidateCount",0,"suggestionOnly",true));}return Map.of("items",result,"total",result.size(),"complete",complete,"basis","仅同门店同方向的净未清候选，按真实引用、金额、日期距离排序；候选不等于已对账，不自动归集，不以缺少候选解释未达");}
 private BigDecimal bankAllocated(TenantPrincipal p,UUID bank){var b=base(p).addValue("bank",bank);boolean corrected=exists("fx_cash_correction");BigDecimal used=jdbc.queryForObject(corrected?"select fx_bank_allocated_amount(:tenantId,:bank,:asOf)+fb_bank_allocated_amount(:tenantId,:bank,:asOf)":"select coalesce((select sum(amount) from fo_bank_match where tenant_id=:tenantId and transaction_id=:bank),0)+fb_bank_allocated_amount(:tenantId,:bank,:asOf)",b,BigDecimal.class);if(exists("fs_settlement"))used=used.add(jdbc.queryForObject("select coalesce(sum(amount),0) from fs_settlement where tenant_id=:tenantId and bank_transaction_id=:bank",b,BigDecimal.class));if(!corrected&&exists("fc_claim_bank_match"))used=used.add(jdbc.queryForObject("select coalesce(sum(amount),0) from fc_claim_bank_match where tenant_id=:tenantId and transaction_id=:bank",b,BigDecimal.class));return used;}
 public Map<String,Object> matchBank(BankMatch in){var p=prepare("finance.pay");if(replay(p,in.requestId(),in.transactionId(),"BANK_MATCH",in))return bankMatches();jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,89))",Map.of("key",p.tenantId()+":bank-match"));var b=base(p).addValue("bank",in.transactionId());var banks=jdbc.queryForList("select t.*,b.hotel_id from fo_bank_transaction t join fo_bank_account b on b.tenant_id=t.tenant_id and b.id=t.bank_account_id where t.tenant_id=:tenantId and t.id=:bank",b);if(banks.isEmpty())throw missing();var bank=banks.getFirst();access.requireOrgScope(uid(bank,"hotel_id"));BigDecimal total=BigDecimal.ZERO;Set<String> keys=new HashSet<>();for(var allocation:in.allocations()){
   if(!keys.add(allocation.sourceType()+allocation.sourceId()))throw bad("同一资金事实分配重复");positive(allocation.amount());Map<String,Object> fact;if(allocation.sourceType().equals("REVENUE")){var facts=jdbc.queryForList("select m.*,e.hotel_id,case when m.kind='RECEIPT' then 'IN' else 'OUT' end direction from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id where m.tenant_id=:tenantId and m.id=:source and m.kind in ('RECEIPT','REFUND')",base(p).addValue("source",allocation.sourceId()));if(facts.isEmpty())throw missing();fact=facts.getFirst();}
   else if(allocation.sourceType().equals("PAYROLL")){access.requirePermission("finance.payroll");var facts=jdbc.queryForList("select y.*,b.hotel_id,'OUT' direction from fb_payroll_payment y join fb_payroll_line l on l.tenant_id=y.tenant_id and l.id=y.line_id join fb_payroll_batch b on b.tenant_id=l.tenant_id and b.id=l.batch_id where y.tenant_id=:tenantId and y.id=:source",base(p).addValue("source",allocation.sourceId()));if(facts.isEmpty())throw missing();fact=facts.getFirst();}
   else if(allocation.sourceType().equals("TAX")){access.requirePermission("finance.tax");var facts=jdbc.queryForList("select t.*,\'OUT\' direction from ft_tax_payment t where t.tenant_id=:tenantId and t.id=:source",base(p).addValue("source",allocation.sourceId()));if(facts.isEmpty())throw missing();fact=facts.getFirst();}
   else if(allocation.sourceType().equals("OPENING")||allocation.sourceType().equals("INTERCOMPANY")){String table=allocation.sourceType().equals("OPENING")?"fb_opening_clearing":"fb_intercompany_settlement";var facts=jdbc.queryForList("select c.*,case when c.kind='RECEIPT' then 'IN' else 'OUT' end direction from "+table+" c where tenant_id=:tenantId and id=:source",base(p).addValue("source",allocation.sourceId()));if(facts.isEmpty())throw missing();fact=facts.getFirst();}else throw bad("资金事实类型未知");
   access.requireOrgScope(uid(fact,"hotel_id"));if(!uid(fact,"hotel_id").equals(uid(bank,"hotel_id"))||!str(fact,"direction").equals(str(bank,"direction")))throw bad("资金事实与银行流水的归属/方向不同");BigDecimal matched=matchedCash(p,allocation.sourceType(),allocation.sourceId()),effective=effectiveCash(p,allocation.sourceType(),allocation.sourceId(),dec(fact,"amount"));if(matched.add(allocation.amount()).compareTo(effective)>0)throw conflict("资金事实剩余可匹配金额不足（已扣差错冲回）");total=total.add(allocation.amount());
  }
  BigDecimal used=bankAllocated(p,in.transactionId());
  if(used.add(total).compareTo(dec(bank,"amount"))>0)throw conflict("银行流水在其他财务来源中已分配，剩余金额不足");for(var a:in.allocations())jdbc.update("insert into fb_bank_match(id,tenant_id,transaction_id,source_type,source_id,amount,request_id,note,actor_id) values(:id,:tenantId,:bank,:type,:source,:amount,:request,:note,:actorId)",b.addValue("id",UUID.randomUUID()).addValue("type",a.sourceType()).addValue("source",a.sourceId()).addValue("amount",money(a.amount())).addValue("request",in.requestId()).addValue("note",in.note()));record(p,in.requestId(),in.transactionId(),"BANK_MATCH",in);return bankMatches();
 }
 private boolean exists(String table){return Boolean.TRUE.equals(jdbc.queryForObject("select to_regclass(:name) is not null",Map.of("name",table),Boolean.class));}
 public Map<String,Object> correctCash(CashCorrection in){var p=prepare("finance.review");if(in.sourceType().equals("PAYROLL"))access.requirePermission("finance.payroll");if(in.sourceType().equals("TAX"))access.requirePermission("finance.tax");if(replay(p,in.requestId(),in.sourceId(),"CASH_CORRECTION",in))return cashFacts();var fact=cashSource(p,in.sourceType(),in.sourceId(),true);var config=configuration(p,uid(fact,"hotel_id"));if(p.actorId().equals(uid(fact,"created_by"))||!Set.of(uid(config,"finance_account_id"),uid(config,"director_account_id")).contains(p.actorId()))throw forbidden();positive(in.amount());LocalDate originalDay=date(fact,"occurred_on");if(in.accountingDate().isBefore(originalDay)||in.accountingDate().isAfter(LocalDate.now(ZoneId.of("Asia/Shanghai"))))throw bad("差错记账日须为原业务日之后、截至今日的开放期间；不改写原业务日");
  jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,89))",Map.of("key",p.tenantId()+":bank-match"));for(var book:jdbc.queryForList("select id from fa_book where tenant_id=:tenantId and hotel_id=:hotel and enabled order by id",base(p).addValue("hotel",fact.get("hotel_id"))))jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,0))",Map.of("key",p.tenantId()+":book:"+book.get("id")));
  var period=jdbc.queryForList("select p.status from fa_book b join fa_period p on p.tenant_id=b.tenant_id and p.book_id=b.id where b.tenant_id=:tenantId and b.hotel_id=:hotel and b.enabled and p.month=:month",base(p).addValue("hotel",fact.get("hotel_id")).addValue("month",YearMonth.from(in.accountingDate()).atDay(1)));if(period.stream().anyMatch(r->"CLOSED".equals(r.get("status"))))throw conflict("差错记账期间已锁定，请选择当前开放期间；不能把差错回写已结月");
  BigDecimal effective=effectiveCash(p,in.sourceType(),in.sourceId(),dec(fact,"amount"));if(in.amount().compareTo(effective)>0)throw conflict("差错冲回超过该原资金事实的净有效金额");
  if(in.sourceType().equals("REVENUE")){var entry=raw("fb_revenue_entry",uid(fact,"entry_id"),p,false);BigDecimal received=movement(p,entry,"RECEIPT"),refunded=movement(p,entry,"REFUND"),redeemed=movement(p,entry,"REDEEM");BigDecimal after=received.subtract(refunded).add(str(fact,"kind").equals("RECEIPT")?in.amount().negate():str(fact,"kind").equals("REFUND")?in.amount():BigDecimal.ZERO);if(str(fact,"kind").equals("REDEEM"))redeemed=redeemed.subtract(in.amount());var latest=latestRevenue(p,entry);BigDecimal ceiling=dec(latest,"amount").subtract(dec(latest,"commission")).subtract(dec(latest,"fee")).subtract(adjustedInto(p,latest));if(after.compareTo(redeemed)<0||after.signum()<0||after.add(redeemedInto(p,latest)).compareTo(ceiling)>0)throw conflict("原收款已被退款/消费核销或后续收款使用，不能盲目冲回；请先核对关联业务并受控调整");}
  var originals=jdbc.queryForList("select * from fa_source_event where tenant_id=:tenantId and source_id=:source and source_type=:type and event_key=:kind",base(p).addValue("source",in.sourceId()).addValue("type",fact.get("accounting_type")).addValue("kind",fact.get("kind")));if(originals.size()!=1)throw conflict("原资金来源会计事件不唯一或缺失，需先核对来源，不可无凭据冲回");
  BigDecimal matched=matchedCash(p,in.sourceType(),in.sourceId()),undo=BigDecimal.ZERO;Set<UUID> seen=new HashSet<>();for(var reversal:in.matchingReversals()){if(!seen.add(reversal.matchId()))throw bad("匹配逆向记录重复");positive(reversal.amount());var matches=jdbc.queryForList("select m.*,m.amount-coalesce((select sum(r.amount) from fb_bank_match_reversal r where r.tenant_id=m.tenant_id and r.match_id=m.id and r.accounting_on<=:asOf),0) effective_amount from fb_bank_match m where m.tenant_id=:tenantId and m.id=:match and m.source_type=:type and m.source_id=:source",base(p).addValue("match",reversal.matchId()).addValue("type",in.sourceType()).addValue("source",in.sourceId()));if(matches.isEmpty()||reversal.amount().compareTo(dec(matches.getFirst(),"effective_amount"))>0)throw conflict("匹配逆向超过原银行分配的有效金额，或不属于本资金事实");undo=undo.add(reversal.amount());}
  BigDecimal required=matched.subtract(effective.subtract(in.amount())).max(BigDecimal.ZERO);if(undo.compareTo(required)<0||undo.compareTo(in.amount().min(matched))>0)throw conflict("已匹配金额必须提交明确匹配逆向事实，至少 "+required.toPlainString()+"，最多 "+in.amount().min(matched).toPlainString()+"；不能删除旧匹配");
  var proof=new LinkedHashMap<String,Object>();proof.put("originalSourceEventId",originals.getFirst().get("id"));proof.put("originalSourceType",fact.get("accounting_type"));proof.put("originalKind",fact.get("kind"));proof.put("originalAmount",dec(fact,"amount").toPlainString());proof.put("effectiveBefore",effective.toPlainString());proof.put("matchedBefore",matched.toPlainString());proof.put("bankMatchingReversal",undo.toPlainString());proof.put("originalBankReference",fact.get("bank_reference"));proof.put("meaning","原登记差错冲回，不是执行真实退款，也不修改真实银行流水");
  jdbc.update("insert into fb_cash_correction(id,tenant_id,source_type,source_id,hotel_id,company_id,original_kind,original_source_event_id,amount,business_date,accounting_on,note,proof,created_by) values(:id,:tenantId,:type,:source,:hotel,:company,:kind,:originalEvent,:amount,:business,:day,:note,cast(:proof as jsonb),:actorId)",base(p).addValue("id",in.requestId()).addValue("type",in.sourceType()).addValue("source",in.sourceId()).addValue("hotel",fact.get("hotel_id")).addValue("company",fact.get("company_id")).addValue("kind",fact.get("kind")).addValue("originalEvent",originals.getFirst().get("id")).addValue("amount",money(in.amount())).addValue("business",originalDay).addValue("day",in.accountingDate()).addValue("note",in.note()).addValue("proof",json(proof)));
  for(var r:in.matchingReversals())jdbc.update("insert into fb_bank_match_reversal(id,tenant_id,match_id,correction_id,amount,accounting_on,created_by) values(:id,:tenantId,:match,:correction,:amount,:day,:actorId)",base(p).addValue("id",UUID.randomUUID()).addValue("match",r.matchId()).addValue("correction",in.requestId()).addValue("amount",money(r.amount())).addValue("day",in.accountingDate()));
  var correctionMetadata=new LinkedHashMap<String,String>();correctionMetadata.put("businessTable","fb_cash_correction");correctionMetadata.put("businessId",in.requestId().toString());correctionMetadata.put("companyId",str(fact,"company_id"));correctionMetadata.put("originalSourceEventId",str(originals.getFirst(),"id"));correctionMetadata.put("originalSourceType",str(fact,"accounting_type"));correctionMetadata.put("sourceId",in.sourceId().toString());if(in.sourceType().equals("INTERCOMPANY")){correctionMetadata.put("transactionId",str(fact,"transaction_id"));correctionMetadata.put("side",str(fact,"side"));}accounting.recordSourceEvent(uid(fact,"hotel_id"),"FB_CASH_CORRECTION_"+in.sourceType(),in.requestId(),str(fact,"kind")+"_CORRECTION",originalDay,in.accountingDate(),money(in.amount()),"资金差错登记独立冲回（不执行转账）",correctionMetadata);record(p,in.requestId(),in.sourceId(),"CASH_CORRECTION",in);return cashFacts();
 }
 private Map<String,Object> cashSource(TenantPrincipal p,String type,UUID id,boolean lockParent){String sql=switch(type){case "REVENUE"->"select m.*,e.hotel_id,e.company_id,e.id parent_id,'fb_revenue_entry' parent_table,'FB_REVENUE_'||e.kind accounting_type from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id where m.tenant_id=:tenantId and m.id=:id and m.kind in ('RECEIPT','REFUND','REDEEM')";case "PAYROLL"->"select y.*,b.hotel_id,b.company_id,b.id parent_id,'fb_payroll_batch' parent_table,'PAYMENT' kind,'FB_PAYROLL' accounting_type from fb_payroll_payment y join fb_payroll_line l on l.tenant_id=y.tenant_id and l.id=y.line_id join fb_payroll_batch b on b.tenant_id=l.tenant_id and b.id=l.batch_id where y.tenant_id=:tenantId and y.id=:id";case "OPENING"->"select c.*,c.subledger_id parent_id,'fm_subledger' parent_table,'FB_OPENING' accounting_type from fb_opening_clearing c where c.tenant_id=:tenantId and c.id=:id";case "TAX"->"select t.*,t.accrual_id parent_id,\'ft_tax_accrual\' parent_table,\'PAYMENT\' kind,\'FB_TAX_PAYMENT\' accounting_type,b.external_id bank_reference from ft_tax_payment t join fo_bank_transaction b on b.tenant_id=t.tenant_id and b.id=t.bank_transaction_id where t.tenant_id=:tenantId and t.id=:id";case "INTERCOMPANY"->"select c.*,c.transaction_id parent_id,'fb_intercompany' parent_table,'FB_INTERCOMPANY_CASH' accounting_type from fb_intercompany_settlement c where c.tenant_id=:tenantId and c.id=:id";default->throw bad("现金事实类型未知");};if(type.equals("PAYROLL"))access.requirePermission("finance.payroll");if(type.equals("TAX"))access.requirePermission("finance.tax");var values=jdbc.queryForList(sql,base(p).addValue("id",id));if(values.isEmpty())throw missing();var row=values.getFirst();access.requireOrgScope(uid(row,"hotel_id"));if(lockParent)jdbc.queryForList("select id from "+str(row,"parent_table")+" where tenant_id=:tenantId and id=:parent for update",base(p).addValue("parent",row.get("parent_id")));return row;}
 private BigDecimal adjustedInto(TenantPrincipal p,Map<String,Object> row){return exists("fb_receivable_adjustment")?jdbc.queryForObject("select fb_receivable_adjusted_amount(:tenantId,:entry,:asOf)",base(p).addValue("entry",row.get("id")),BigDecimal.class):BigDecimal.ZERO;}
 private BigDecimal effectiveCash(TenantPrincipal p,String type,UUID source,BigDecimal original){return jdbc.queryForObject("select fb_cash_effective_amount(:tenantId,:type,:source,:original,:asOf)",base(p).addValue("type",type).addValue("source",source).addValue("original",original),BigDecimal.class);}
 private BigDecimal matchedCash(TenantPrincipal p,String type,UUID source){return jdbc.queryForObject("select fb_bank_matched_amount(:tenantId,:type,:source,:asOf)",base(p).addValue("type",type).addValue("source",source),BigDecimal.class);}
 public Map<String,Object> cashCorrections(){var p=prepare("finance.read","finance.review");return list("select d.* from fb_cash_correction d where d.tenant_id=:tenantId and "+scope("d")+" and (:payroll or d.source_type<>'PAYROLL') and (:tax or d.source_type<>'TAX') order by accounting_on desc,id",base(p).addValue("payroll",has(p,"finance.payroll")).addValue("tax",has(p,"finance.tax")));}
 private Map<String,Object> latestRevenue(TenantPrincipal p,Map<String,Object> row){var list=jdbc.queryForList("select e.* from fb_revenue_entry e join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id join fb_revenue_batch old on old.tenant_id=b.tenant_id and old.id=:batch where e.tenant_id=:tenantId and e.hotel_id=:hotel and e.external_id=:external and e.active and b.source=old.source and b.channel=old.channel and b.business_date=old.business_date",base(p).addValue("batch",row.get("batch_id")).addValue("hotel",row.get("hotel_id")).addValue("external",row.get("external_id")));return list.isEmpty()?row:list.getFirst();}
 private List<Map<String,Object>> consolidationBalances(MapSqlParameterSource b){return jdbc.queryForList("select report_line,category,sum(debit) debit,sum(credit) credit from (select a.report_line,a.category,l.debit,l.credit from fa_voucher v join fa_book b on b.tenant_id=v.tenant_id and b.id=v.book_id join fa_voucher_line l on l.tenant_id=v.tenant_id and l.voucher_id=v.id join fa_account a on a.tenant_id=l.tenant_id and a.id=l.account_id where v.tenant_id=:tenantId and b.hotel_id in (:hotels) and v.accounting_date<:end and (a.category not in ('REVENUE','EXPENSE') or v.accounting_date>=:month) and v.status='POSTED' and (:payroll or not exists(select 1 from fa_source_event s where s.tenant_id=v.tenant_id and s.voucher_id=v.id and s.source_type like '%PAYROLL%')) union all select a.report_line,a.category,o.debit,o.credit from fa_opening_balance o join fa_book b on b.tenant_id=o.tenant_id and b.id=o.book_id join fa_account a on a.tenant_id=o.tenant_id and a.id=o.account_id where o.tenant_id=:tenantId and b.hotel_id in (:hotels) and b.start_month<=:month and a.category not in ('REVENUE','EXPENSE')) facts group by report_line,category order by report_line",b);}
 public Map<String,Object> openingItems(){var p=prepare("finance.read","finance.pay","finance.review");if(!exists("fm_subledger"))return Map.of("items",List.of(),"status","MIGRATION_NOT_INSTALLED");return list("select s.*,b.hotel_id,b.company_id,coalesce((select sum(fb_cash_effective_amount(c.tenant_id,'OPENING',c.id,c.amount,:asOf)) from fb_opening_clearing c where c.tenant_id=s.tenant_id and c.subledger_id=s.id),0) cleared_amount,s.remaining_amount-coalesce((select sum(fb_cash_effective_amount(c.tenant_id,'OPENING',c.id,c.amount,:asOf)) from fb_opening_clearing c where c.tenant_id=s.tenant_id and c.subledger_id=s.id),0) outstanding_amount from fm_subledger s join fa_book b on b.tenant_id=s.tenant_id and b.id=s.book_id where s.tenant_id=:tenantId and s.kind='OPEN_ITEM' and s.status='ACTIVE' and "+scope("b")+" order by s.due_date,s.id",base(p));}
 public Map<String,Object> clearOpening(UUID id,OpeningClear in){var p=prepare("finance.pay");if(replay(p,in.requestId(),id,"OPENING_CLEAR",in))return openingItems();if(!exists("fm_subledger"))throw conflict("期初迁移尚未安装");positive(in.amount());var rows=jdbc.queryForList("select s.*,b.hotel_id,b.company_id from fm_subledger s join fa_book b on b.tenant_id=s.tenant_id and b.id=s.book_id where s.tenant_id=:tenantId and s.id=:id and s.kind='OPEN_ITEM' and s.status='ACTIVE' for update of s",base(p).addValue("id",id));if(rows.isEmpty())throw missing();var row=rows.getFirst();access.requireOrgScope(uid(row,"hotel_id"));var config=configuration(p,uid(row,"hotel_id"));if(!uid(row,"company_id").equals(uid(config,"company_id"))||!p.actorId().equals(uid(config,"cashier_account_id")))throw forbidden();if(in.occurredOn().isBefore(date(row,"business_date")))throw bad("清偿日不能早于期初来源日");BigDecimal prior=jdbc.queryForObject("select coalesce(sum(fb_cash_effective_amount(tenant_id,'OPENING',id,amount,:asOf)),0) from fb_opening_clearing where tenant_id=:tenantId and subledger_id=:id",base(p).addValue("id",id),BigDecimal.class);if(prior.add(in.amount()).compareTo(dec(row,"remaining_amount"))>0)throw conflict("清偿超过已核对ACTIVE期初未清余额");String kind=str(row,"direction").equals("DEBIT")?"RECEIPT":"PAYMENT";
  jdbc.update("insert into fb_opening_clearing(id,tenant_id,subledger_id,hotel_id,company_id,kind,amount,occurred_on,bank_reference,created_by) values(:clear,:tenantId,:id,:hotel,:company,:kind,:amount,:day,:reference,:actorId)",base(p).addValue("clear",in.requestId()).addValue("id",id).addValue("hotel",row.get("hotel_id")).addValue("company",row.get("company_id")).addValue("kind",kind).addValue("amount",money(in.amount())).addValue("day",in.occurredOn()).addValue("reference",in.bankReference()));var fact=jdbc.queryForMap("select * from fb_opening_clearing where tenant_id=:tenantId and id=:id",base(p).addValue("id",in.requestId()));event(p,fact,"fb_opening_clearing","FB_OPENING",kind,in.amount(),in.occurredOn(),in.requestId(),Map.of("subledgerId",id.toString(),"accountCode",str(row,"account_code"),"basis","只清偿已核对期初，不重复确认收入成本"));record(p,in.requestId(),id,"OPENING_CLEAR",in);return openingItems();
 }

 public void authorizeAttachment(String domain,UUID id){TenantPrincipal p;if(domain.equals("PAYROLL"))p=prepare("finance.payroll");else if(domain.equals("TAX")||domain.equals("OUTPUT"))p=prepare("finance.tax");else p=prepare("finance.read","finance.review");load(domainTable(domain),id,p,false);}
 public Map<String,Object> registerAttachment(String domain,UUID id,UUID attachment,String name,String media,long size,String sha,String key,String scan){authorizeAttachment(domain,id);var p=access.principal();var row=load(domainTable(domain),id,p,false);var old=jdbc.queryForList("select * from fb_attachment where tenant_id=:tenantId and id=:id",base(p).addValue("id",attachment));if(!old.isEmpty()){if(!sha.equals(old.getFirst().get("sha256"))||!id.equals(uid(old.getFirst(),"resource_id")))throw conflict("原件编号已被使用，禁止覆盖");return external(old.getFirst());}
  jdbc.update("insert into fb_attachment(id,tenant_id,domain,resource_id,hotel_id,original_name,media_type,size_bytes,sha256,object_key,scan_status,uploaded_by) values(:attachment,:tenantId,:domain,:id,:hotel,:name,:media,:size,:sha,:key,:scan,:actorId)",base(p).addValue("attachment",attachment).addValue("domain",domain).addValue("id",id).addValue("hotel",uid(row,"hotel_id")).addValue("name",name).addValue("media",media).addValue("size",size).addValue("sha",sha).addValue("key",key).addValue("scan",scan));audit.record("FINANCE_BUSINESS_ORIGINAL_ARCHIVED","FINANCE_BUSINESS",id,json(Map.of("attachmentId",attachment,"sha256",sha)));return attachment(domain,id,attachment);
 }
 public Map<String,Object> attachment(String domain,UUID id,UUID attachment){authorizeAttachment(domain,id);var p=access.principal();var rows=jdbc.queryForList("select * from fb_attachment where tenant_id=:tenantId and id=:attachment and domain=:domain and resource_id=:id",base(p).addValue("attachment",attachment).addValue("domain",domain).addValue("id",id));if(rows.isEmpty())throw missing();return rows.getFirst();}
 private String domainTable(String domain){return switch(domain){case "REVENUE"->"fb_revenue_batch";case "PAYROLL"->"fb_payroll_batch";case "OUTPUT"->"fb_output_request";case "TAX"->"fb_tax_return";default->throw bad("档案域未知");};}
 private List<Map<String,Object>> attachments(TenantPrincipal p,String domain,UUID id){return rows("select id,domain,resource_id,original_name,media_type,size_bytes,sha256,scan_status,created_at from fb_attachment where tenant_id=:tenantId and resource_id=:id and domain=:domain order by created_at,id",base(p).addValue("id",id).addValue("domain",domain));}
 private void notifyReview(TenantPrincipal p,String type,UUID source,UUID recipient,int version){jdbc.update("insert into notification(tenant_id,recipient_account_id,notification_type,title,content,source_type,source_id,idempotency_key) values(:tenantId,:recipient,'FINANCE_REVIEW_PENDING','财务业务待独立核对','有一笔财务业务等待您核对来源原件及确认。消息不含工资或税务明细，办理权限以当前任职、范围和独立审核节点为准。',:type,:id,:key) on conflict(tenant_id,recipient_account_id,idempotency_key) do nothing",base(p).addValue("recipient",recipient).addValue("type",type).addValue("id",source).addValue("key",type+":"+source+":REVIEW:"+version+":"+recipient));}
 private void requireOriginal(TenantPrincipal p,String domain,UUID id){if(jdbc.queryForObject("select count(*) from fb_attachment where tenant_id=:tenantId and domain=:domain and resource_id=:id",base(p).addValue("domain",domain).addValue("id",id),Integer.class)==0)throw conflict("请先上传经确认的来源原始文件；文本引用不能代替原件");}
 private void requireAttachment(TenantPrincipal p,String domain,UUID id,UUID attachment){attachment(domain,id,attachment);}
 private TenantPrincipal prepare(String... permissions){access.requireAnyPermission(permissions);var p=access.principal();db.apply(p.tenantId());return p;}
 private UUID company(TenantPrincipal p,UUID hotel){access.requireOrgScope(hotel);return uid(configuration(p,hotel),"company_id");}
 private Map<String,Object> configuration(TenantPrincipal p,UUID hotel){var values=jdbc.queryForList("select * from finance_store_config where tenant_id=:tenantId and hotel_id=:hotel and enabled and workflow_version=2",base(p).addValue("hotel",hotel));if(values.isEmpty())throw conflict("组织财务主体及审批尚未发布，请先完成后台配置");return values.getFirst();}
 private MapSqlParameterSource base(TenantPrincipal p){return new MapSqlParameterSource("tenantId",p.tenantId()).addValue("actorId",p.actorId()).addValue("asOf",LocalDate.now(ZoneId.of("Asia/Shanghai"))).addValue("tenantScope",p.hasTenantScope()).addValue("scopeIds",p.orgScopes().isEmpty()?List.of(new UUID(0,0)):p.orgScopes());}
 private static String scope(String alias){return "(:tenantScope or "+alias+".hotel_id in (:scopeIds))";}
 private Map<String,Object> load(String table,UUID id,TenantPrincipal p,boolean locked){var row=raw(table,id,p,locked);access.requireOrgScope(uid(row,"hotel_id"));if(table.equals("fb_tax_return"))FinanceTaxScope.frozen(jdbc,access,p,row);return row;}
 private Map<String,Object> raw(String table,UUID id,TenantPrincipal p,boolean locked){if(!Set.of("fb_revenue_batch","fb_revenue_entry","fb_payroll_batch","fb_intercompany","fb_consolidation_scope","fb_consolidation_worksheet","fb_output_request","fb_output_invoice","fb_tax_policy","fb_input_tax","fb_tax_return").contains(table))throw new IllegalArgumentException("Invalid internal table");var values=jdbc.queryForList("select * from "+table+" where tenant_id=:tenantId and id=:id"+(locked?" for update":""),base(p).addValue("id",id));if(values.isEmpty())throw missing();return values.getFirst();}
 private void reviewer(TenantPrincipal p,Map<String,Object> row,String creator,String reviewer){if(p.actorId().equals(uid(row,creator))||!p.actorId().equals(uid(row,reviewer)))throw forbidden();}
 private void independent(TenantPrincipal p,UUID id){if(p.actorId().equals(id))throw bad("编制人和确认/付款人必须独立");}
 private void account(TenantPrincipal p,UUID id){if(jdbc.queryForObject("select count(*) from user_account where tenant_id=:tenantId and id=:id and status='ACTIVE'",base(p).addValue("id",id),Integer.class)!=1)throw bad("相关员工账号无效");}
 private void event(TenantPrincipal p,Map<String,Object> row,String table,String type,String key,BigDecimal amount,LocalDate date,UUID sourceId,Map<String,String> extra){var metadata=new LinkedHashMap<>(extra);metadata.put("businessTable",table);metadata.put("businessId",str(row,"id"));metadata.put("companyId",str(row,"company_id"));metadata.put("externalExecution","NONE");if(type.equals("FB_INTERCOMPANY"))accounting.recordBilateralSourceEvent(uid(row,"hotel_id"),type,sourceId,key,date,date,money(amount),"财务业务事实 "+type,metadata);else accounting.recordSourceEvent(uid(row,"hotel_id"),type,sourceId,key,date,date,money(amount),"财务业务事实 "+type,metadata);}
 private BigDecimal reservedInvoiceAmount(TenantPrincipal p,Map<String,Object> row){return jdbc.queryForObject("select coalesce(sum(l.amount),0) from fb_output_line l join fb_output_request q on q.tenant_id=l.tenant_id and q.id=l.request_id join fb_revenue_entry e on e.tenant_id=l.tenant_id and e.id=l.entry_id join fb_revenue_batch b on b.tenant_id=e.tenant_id and b.id=e.batch_id join fb_revenue_batch current_batch on current_batch.tenant_id=b.tenant_id and current_batch.id=:batch where l.tenant_id=:tenantId and e.hotel_id=:hotel and e.external_id=:external and b.source=current_batch.source and b.channel=current_batch.channel and b.business_date=current_batch.business_date and q.status<>'CANCELLED'",base(p).addValue("batch",uid(row,"batch_id")).addValue("hotel",uid(row,"hotel_id")).addValue("external",str(row,"external_id")),BigDecimal.class);}
 private void version(Map<String,Object> row,int expected){if(((Number)row.get("version")).intValue()!=expected)throw conflict("状态已改变，请刷新后再办理");}
 private void lock(TenantPrincipal p,String key){jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(:key,92))",Map.of("key",p.tenantId()+":"+key));}
 private boolean replay(TenantPrincipal p,UUID request,UUID resource,String operation,Object input){lock(p,"command:"+request);var values=jdbc.queryForList("select * from fb_command where tenant_id=:tenantId and request_id=:request",base(p).addValue("request",request));if(values.isEmpty())return false;var old=values.getFirst();if(!resource.equals(uid(old,"resource_id"))||!operation.equals(str(old,"operation"))||!hash(input).equals(str(old,"request_hash")))throw conflict("请求编号已用于不同内容，不能复用");return true;}
 private void record(TenantPrincipal p,UUID request,UUID resource,String operation,Object input){jdbc.update("insert into fb_command(tenant_id,request_id,resource_id,operation,request_hash) values(:tenantId,:request,:resource,:operation,:hash)",base(p).addValue("request",request).addValue("resource",resource).addValue("operation",operation).addValue("hash",hash(input)));audit.record("FINANCE_BUSINESS_"+operation,"FINANCE_BUSINESS",resource,"{}");}
 private Map<String,Object> list(String sql,MapSqlParameterSource b){var items=rows(sql,b);return Map.of("items",items,"total",items.size());}
 private List<Map<String,Object>> rows(String sql,MapSqlParameterSource b){return jdbc.queryForList(sql,b).stream().map(this::external).toList();}
 private Map<String,Object> external(Map<String,Object> input){var result=new LinkedHashMap<String,Object>();input.forEach((key,value)->{if(value!=null&&Set.of("earnings","deductions","employer_costs","basis_snapshot","hotel_ids","rules","snapshot","fields","proof").contains(key))value=parse(value);result.put(camel(key),safe(value));});return result;}
 private Object safe(Object value){if(value instanceof BigDecimal b)return b.toPlainString();if(value instanceof Map<?,?> m){var out=new LinkedHashMap<String,Object>();m.forEach((k,v)->out.put(k.toString(),safe(v)));return out;}if(value instanceof Collection<?> c)return c.stream().map(this::safe).toList();return value;}
 private Object parse(Object value){try{return mapper.readerFor(Object.class).with(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS).readValue(value.toString());}catch(Exception e){throw new IllegalStateException("财务资料读取失败",e);}}
 @SuppressWarnings("unchecked") private Map<String,Object> object(Object value){return (Map<String,Object>)parse(value);}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> objects(Object value){return (List<Map<String,Object>>)parse(value);}
 private List<UUID> uuidList(Object value){return ((List<?>)parse(value)).stream().map(v->UUID.fromString(v.toString())).toList();}
 private String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("财务资料不可序列化",e);}}
 private String hash(Object value){return FinanceService.hash(json(value));}
 private static String camel(String key){StringBuilder out=new StringBuilder();boolean upper=false;for(char c:key.toCharArray()){if(c=='_')upper=true;else{out.append(upper?Character.toUpperCase(c):c);upper=false;}}return out.toString();}
 private static boolean has(TenantPrincipal p,String code){return p.hasPermission(code)||p.hasPermission("*");}
 private static UUID uid(Map<String,Object> r,String key){return r.get(key)==null?null:UUID.fromString(r.get(key).toString());}
 private static String str(Map<String,Object> r,String key){return Objects.toString(r.get(key),"");}
 private static BigDecimal dec(Map<String,Object> r,String key){return new BigDecimal(r.get(key).toString());}
 private static LocalDate date(Map<String,Object> r,String key){return LocalDate.parse(r.get(key).toString());}
 private static LocalDate month(String text){try{var value=YearMonth.parse(text);if(value.getYear()<2000||value.getYear()>2200)throw new IllegalArgumentException();return value.atDay(1);}catch(Exception e){throw bad("期间应为YYYY-MM");}}
 private static BigDecimal money(BigDecimal n){try{if(n==null)return invalidMoney();BigDecimal exact=n.setScale(2,RoundingMode.UNNECESSARY);if(exact.precision()>18)return invalidMoney();return exact;}catch(ArithmeticException e){return invalidMoney();}}
 private static BigDecimal invalidMoney(){throw bad("金额须为不超过18位的精确分值，不接受隐式四舍五入");}
 private static void nonnegative(BigDecimal amount){if(money(amount).signum()<0)throw bad("金额不能为负");}
 private static void positive(BigDecimal amount){if(money(amount).signum()<=0)throw bad("金额必须大于0");}
 private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}
 private static ResponseStatusException conflict(String text){return new ResponseStatusException(HttpStatus.CONFLICT,text);}
 private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"资料不存在或当前身份不可查看");}
 private static ResponseStatusException forbidden(){return new ResponseStatusException(HttpStatus.FORBIDDEN,"当前账号不是本环节独立授权办理人");}
}
